nav.example:
# 使用`sudo`重新执行上一个命令
sudo !!
# 通过在`history`中出现的`行号`来调取命令
!{{行号}}
# 调取`history`中的倒数第`数字`条命令
!-{{数字}}
# 调取以`字符串`开头的最近执行的命令
!{{字符串}}

# 使用`regex`式搜索关键字
apropos {{正则表达式}}
# 搜索时不限制输出到终端宽度
apropos {{[-l|--long]}} {{正则表达式}}
# 搜索与给定的所有表达式都匹配的页面
apropos {{正则表达式_1}} {{[-a|--and]}} {{正则表达式_2}} {{[-a|--and]}} {{正则表达式_3}}

# 设置环境变量
export {{变量名}}={{值}}
# 向环境变量 `$PATH` 追加一个路径名
export PATH=$PATH:{{追加的 path 路径}}

# 展示一条命令的使用手册分页
man {{command}}
# 在浏览器中打开一条命令的使用手册分页 (`$BROWSER` 环境变量可以替换 `=browser_name`)
man {{[-H|--html=]}}{{browser_name}} {{command}}
# 从第七章节展示一条命令的使用手册分页
man 7 {{command}}
# 列表展示一条命令的所有可用章节
man {{[-f|--whatis]}} {{command}}

# 读取键盘输入的数据赋值给变量
read {{变量}}
# 将您输入的每一行存储为数组一个元素
read -a {{数组}}
# 指定要读取的字符数，将数据赋值给变量
read -n {{字符数}} {{变量}}
# 将多个数据依次赋值给多个变量
read {{_ 变量1 _ 变量2}} <<<"{{The surname is Bond}}"

# 执行指定文件中的内容
source {{路径/到/文件}}
# 执行指定文件中的内容（也可以用`.`替代`source`）
. {{路径/到/文件}}

# 打印指定命令的 tldr 页面（提示：这就是你来到这里的方式！）
tldr {{命令}}
# 打印指定子命令的 tldr 页面
tldr {{命令}} {{子命令}}
# 用指定语言打印命令的 tldr 页面（如果没有，返回英语）
tldr {{[-L|--language]}} {{语言代码}} {{命令}}
# 打印指定平台的命令的 tldr 页面
tldr {{[-p|--platform]}} {{android|common|freebsd|linux|osx|netbsd|openbsd|sunos|windows}} {{命令}}

# 列出命令和预期事件的名称
trap
# 在接收到信号时执行命令
trap 'echo "捕获到信号 {{SIGHUP}}"' {{HUP}}
# 移除命令
trap - {{HUP}} {{INT}}

# 删除变量 `foo`，如果该变量不存在则删除函数 `foo`
unset {{foo}}
# 删除变量 foo 和 bar
unset -v {{foo bar ...}}
# 删除函数 my_func
unset -f {{my_func}}

# 在`$PATH`中寻找可执行文件并打印第一个匹配的结果
which {{executable}}
# 如果有多个匹配结果则打印所有结果
which {{[-a|--all]}} {{executable}}

# 授予 direnv 当前目录中加载 `.envrc`
direnv allow {{.}}
# 撤销在当前目录加载 `.envrc` 的授权
direnv deny {{.}}
# 使用默认编辑器编辑 `.envrc` 并在退出时重载环境
direnv edit {{.}}
# 触发环境重载
direnv reload

# 跳转到一个名字带有 "foo" 的文件夹
z {{foo}}
# 跳转到一个名字带有 "foo" 并且后面带有 "bar" 的文件夹（例：`fooesbar`）
z {{foo}} {{bar}}
# 跳转到名字带有 "foo" 并且拥有最高访问次数的文件夹
z -r {{foo}}
# 跳转到最近使用的名字带有 "foo" 的文件夹
z -t {{foo}}

# 转到名称中包含 "foo" 的排名最高的目录
zoxide query {{foo}}
# 转到名称中依次包含 "foo" 和 "bar" 的排名最高的目录
zoxide query {{foo}} {{bar}}
# 启动一个交互式目录搜索（需要 `fzf`）
zoxide query --interactive
# 添加一个目录或提升其排名
zoxide add {{路径/到/目录}}

# 隔离变量名
echo ${{{HOME}work}}
# 使用大括号展开序列
echo {{{1..3}}} {{{a..c}}}{{{dir1,dir2,dir3}}}
# 在返回文本之前检查 `variable` 是否已设置
echo ${{{variable:+variable is set and contains $variable}}}
# 在 `variable` 未设置的情况下设置默认值
echo ${{{variable:-default}}}

# 定位命令相关文件
whereis {{命令}}
# 只查找二进制文件
whereis -b {{命令}}
# 只查找手册
whereis -m {{命令}}

file.example:
# 仅显示文件名
basename {{路径/到/文件}}
# 显示路径字符最右边表示目录的字符
basename {{路径/到/目录/}}
# 展示无后缀的文件名称
basename {{路径/到/文件}} {{后缀}}

# 可访问书签清单
l
# 保存当前目录到某书签里
s {{书签名}}
# 跳转到指定书签
g {{书签名}}
# 打印书签目录内容
p {{书签名}}

# 将文件复制到另一个位置
cp {{路径/到/源_文件.ext}} {{路径/到/目标文件.ext}}
# 将文件复制到另一个文件夹，并保留原来的文件名
cp {{路径/到/源文件.ext}} {{路径/到/目标的目录}}
# 以递归方式将文件夹内的内容复制到另一个位置（如果目标文件夹存在，则将此文件夹复制到目标文件夹中）
cp {{[-r|--recursive]}} {{路径/到/源目录}} {{路径/到/目标目录}}
# 以详细模式递归复制目录（在复制文件时显示文件信息）
cp {{[-vr|--verbose --recursive]}} {{路径/到/源目录}} {{路径/到/目标目录}}

# 显示磁盘使用情况
df
# 以可读的形式显示磁盘使用情况
df {{[-h|--human-readable]}}
# 显示给定文件或目录的磁盘使用情况
df {{路径/到/文件或目录}}
# 包括空闲 inode 数量的统计信息
df {{[-i|--inodes]}}

# 以给定单位（B/KiB/MiB）列出目录和所有子目录的大小
du -{{b|k|m}} {{路径/到/目录}}
# 以可读形式列出目录和任何子目录的大小（即自动转换为的合适的单位）
du {{[-h|--human-readable]}} {{路径/到/目录}}
# 以可读单位显示目录大小
du {{[-sh|--summarize --human-readable]}} {{路径/到/目录}}
# 列出目录以及其中所有文件和目录的可读大小
du {{[-ah|--all --human-readable]}} {{路径/到/目录}}

# 每行列出一个文件
exa {{[-1|--oneline]}}
# 列出所有文件，包括隐藏文件
exa {{[-a|--all]}}
# 以长格式列出所有文件（包含权限、所有者、大小和修改日期）
exa {{[-l|--long]}} {{[-a|--all]}}
# 列出文件，最大的排在最上面
exa {{[-r|--reverse]}} {{[-s|--sort]}} {{size}}

# 每行列出一个文件
eza {{[-1|--oneline]}}
# 列出所有文件，包括隐藏文件
eza {{[-a|--all]}}
# 以长格式列出所有文件（包含权限、所有者、大小和修改日期）
eza {{[-al|--all --long]}}
# 列出文件，最大的排在最上面
eza {{[-r|--reverse]}} {{[-s|--sort]}} {{size}}

# 在当前目录中递归查找匹配特定模式的文件
fd "{{正则表达式}}"
# 在特定目录中查找文件
fd "{{正则表达式}}" {{路径/到/文件}}
# 查找具有特定扩展名的文件
fd {{[-e|--extension]}} {{扩展名}}
# 仅查找匹配特定模式的文件夹
fd "{{正则表达式}}" {{[-t|--type]}} {{[d|directory]}}

# 提供指定文件类型的描述，对于没有文件扩展名的文件可以正常工作
file {{文件名}}
# 查看压缩文件并确定其中的文件类型
file {{[-z|--uncompress]}} {{xxx.zip}}
# 允许文件与特殊文件或设备文件一起使用
file {{[-s|--special-files]}} {{文件名}}
# 不要在第一个文件类型匹配时停止；继续执行直到文件结束
file {{[-k|--keep-going]}} {{文件名}}

# 创建指向文件或目录的符号链接
ln {{[-s|--symbolic]}} /{{路径/到/文件或目录}} {{路径/到/符号链接}}
# 创建相对于链接所在位置的符号链接
ln {{[-s|--symbolic]}} {{路径/到/文件或目录}} {{路径/到/符号链接}}
# 覆盖现有的符号链接以指向其他文件
ln {{[-sf|--symbolic --force]}} /{{路径/到/新文件}} {{路径/到/符号链接}}
# 创建文件的硬链接
ln /{{路径/到/文件}} {{路径/到/硬链接}}

# 列出目录中的文件，每个文件占一行
ls -1
# 列出包含隐藏文件的所有文件
ls {{[-a|--all]}}
# 列出所有文件，如果是目录，则在目录名后面加上「/」
ls {{[-F|--classify]}}
# 列出包含隐藏文件的所有文件信息，包括权限，所有者，大小和修改日期
ls {{[-la|-l --all]}}

# 创建特定目录
mkdir {{路径/到/目录1 路径/到/目录2 ...}}
# 根据需要创建特定目录及其父目录
mkdir {{[-p|--parents]}} {{路径/到/目录1 路径/到/目录2 ...}}
# 创建具有特定权限的目录
mkdir {{[-m|--mode]}} {{u=rwx,g=rw,o=r}} {{路径/到/目录1 路径/到/目录2 ...}}

# 重命名文件或目录，当目标不是一个已存在的目录时
mv {{路径/到/源}} {{路径/到/目标}}
# 将文件或目录移动到已存在的目录中
mv {{路径/到/源}} {{路径/到/已存在的目录}}
# 将多个文件移动到已存在的目录中，并保持文件名不变
mv {{路径/到/源1 路径/到/源2 ...}} {{路径/到/已存在的目录}}
# 覆盖现有文件前无需确认
mv {{[-f|--force]}} {{路径/到/源}} {{路径/到/目标}}

# 删除指定文件
rm {{路径/到/文件1 路径/到/文件2 ...}}
# 删除指定文件，忽略不存在的文件
rm {{[-f|--force]}} {{路径/到/文件1 路径/到/文件2 ...}}
# 交互式地删除多个文件，每次删除前都会有提示
rm {{[-i|--interactive]}} {{路径/到/文件1 路径/到/文件2 ...}}
# 删除文件并打印删除信息
rm {{[-v|--verbose]}} {{路径/到/文件1 路径/到/文件2 ...}}

# 删除空目录，使用 `rm -r` 删除非空目录
rmdir {{路径/到/目录}}
# 删除目标及其父目录（对嵌套的目录有用）
rmdir -p {{路径/到/目录}}

# 创建指定的文件
touch {{路径/到/文件1 路径/到/文件2 ...}}
# 将文件的访问(a)或修改时间(m)设置为当前时间，如果文件不存在则不创建(-c)
touch {{[-c|--no-create]}} -{{a|m}} {{路径/到/文件1 路径/到/文件2 ...}}
# 将文件时间(-t)设置为指定值，如果文件不存在则不创建(-c)
touch {{[-c|--no-create]}} -t {{YYYYMMDDHHMM.SS}} {{路径/到/文件1 路径/到/文件2 ...}}
# 将文件时间设置为另一文件(-r,即文件 3)的时间，如果文件不存在则不创建(-c)
touch {{[-c|--no-create]}} {{[-r|--reference]}} {{路径/到/文件3}} {{路径/到/文件1 路径/到/文件2 ...}}

# 复制文件到目标目录
install {{路径/到/源文件1 路径/到/源文件2 ...}} {{路径/到/目标目录}}
# 复制文件到目标目录，并设置其所有权
install {{[-o|--owner]}} {{用户}} {{路径/到/源文件1 路径/到/源文件2 ...}} {{路径/到/目标目录}}
# 复制文件到目标目录，并设置其所属组
install {{[-g|--group]}} {{用户组}} {{路径/到/源文件1 路径/到/源文件2 ...}} {{路径/到/目标目录}}
# 复制文件到目标目录，并设置其权限
install {{[-m|--mode]}} {{+x}} {{路径/到/源文件1 路径/到/源文件2 ...}} {{路径/到/目标目录}}

# 搜索单个目录
jdupes {{路径/到/目录}}
# 搜索多个目录
jdupes {{目录1 目录2 ...}}
# 递归地搜索所有目录
jdupes {{[-r|--recurse]}} {{路径/到/目录}}
# 递归地搜索目录，并让用户选择要保留的文件
jdupes {{[-d|--delete]}} {{[-r|--recurse]}} {{路径/到/目录}}

# 创建一个 15 千字节的空文件
mkfile -n 15k {{文件名}}
# 创建给定大小和单位的文件（bytes, KB, MB, GB）
mkfile -n {{大小}}{{b|k|m|g}} {{文件名}}
# 创建两个 4 兆字节的文件
mkfile -n 4m {{文件名 1}} {{文件名 2}}

# 创建块设备
sudo mknod {{路径/到/设备文件}} b {{主设备号}} {{次设备号}}
# 创建字符设备
sudo mknod {{路径/到/设备文件}} c {{主设备号}} {{次设备号}}
# 创建先进先出（队列）设备
sudo mknod {{路径/到/设备文件}} p
# 使用 SELinux 默认安全上下文创建设备文件
sudo mknod {{[-Z|--context]}} {{路径/到/设备文件}} {{类型}} {{主设备号}} {{次设备号}}

view.example:
# 添加一个新缩写
abbr {{[-a|--add]}} {{缩写名}} {{命令}} {{命令参数}}
# 重命名一个已有的缩写
abbr --rename {{旧缩写名}} {{新缩写名}}
# 清除一个已有的缩写
abbr {{[-e|--erase]}} {{缩写名}}
# 用 SSH 导入另一台主机上定义的缩写
ssh {{主机名}} abbr {{[-s|--show]}} | source

# 寻找内容包含"小明"的文件，并列出所在的行数
ag {{小明}}
# 在指定目录中寻找内容包含 "foo" 的文件
ag {{小明}} {{指定的目录}}
# 寻找内容包含 "foo" 的文件，但只列出文件名
ag -l {{小明}}
# 忽略大小写，寻找内容包含 "ABC" 的文件，并只输出匹配的内容，而非整行
ag -i -o {{ABC}}

# 以空格为分隔符，打印文件每行第五列（也称作字段）
awk '{print $5}' {{文件名}}
# 以空格为分隔符，打印文件包含“foo” 的所有行的第二列
awk '/{{foo}}/ {print $2}' {{文件名}}
# 以逗号而不是空格作为分隔符，打印文件每行的最后一列
awk -F ',' '{print $NF}' {{文件名}}
# 计算文件的第一列数值之和并打印
awk '{s+=$1} END {print s}' {{文件名}}

# 使用美化样式打印一个或多个文件的内容到 `stdout`
bat {{路径/到/文件1 路径/到/文件2 ...}}
# 将多个文件连接成一个目标文件
bat {{路径/到/文件1 路径/到/文件2 ...}} >{{路径/到/目标文件}}
# 移除修饰并禁用分页
bat {{[-pp|--style plain --pager never]}} {{路径/到/文件}}
# 使用不同的背景颜色高亮显示特定行或一行范围
bat {{[-H|--highlight-line]}} {{10|5:10|:10|10:|10:+5}} {{路径/到/文件}}

# 将文件内容打印到 `stdout`
cat {{路径/到/文件}}
# 将多个文件连接到一个输出文件
cat {{路径/到/文件1 路径/到/文件2 ...}} >{{路径/到/输出文件}}
# 将多个文件附加到输出文件
cat {{路径/到/文件1 路径/到/文件2 ...}} >>{{路径/到/输出文件}}
# 将 `stdin` 写入文件
cat - >{{路径/到/文件}}

# 打印每行的特定字符/或属性范围
{{命令}} | cut --{{characters|fields}} {{1|1,10|1-10|1-|-10}}
# 打印每行由指定分隔符分割的属性范围
{{命令}} | cut {{[-d|--delimiter]}} "{{分隔符}}" {{[-f|--fields]}} {{1|1,10|1-10|1-|-10}}
# 打印文件每行的字符范围
cut {{[-c|--characters]}} {{1|1,10|1-10|1-|-10}} {{路径/到/文件}}
# 打印以 `NUL` 结尾的行的特定字段（例如 `find . -print0`）而不是换行符
{{命令}} | cut {{[-z|--zero-terminated]}} {{[-f|--fields]}} {{1}}

# 比较文件或目录
delta {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}
# 比较文件或目录，显示行号
delta {{[-n|--line-numbers]}} {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}
# 比较文件或目录，并排显示差异
delta {{[-s|--side-by-side]}} {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}
# 比较文件或目录，忽略任何 Git 配置设置
delta --no-gitconfig {{路径/到/旧文件或目录}} {{路径/到/新文件或目录}}

# 比较文件 （列出从`原文件`到`新文件`的修改）
diff {{原文件}} {{新文件}}
# 比较文件，忽视空白字符
diff {{[-w|--ignore-all-space]}} {{原文件}} {{新文件}}
# 比较文件，并排展示文件差异
diff {{[-y|--side-by-side]}} {{原文件}} {{新文件}}
# 比较文件，以统一形式展示不同区别 （ 形式同 `git diff`）
diff {{[-u|--unified]}} {{源文件}} {{新文件}}

# 更改文件的行尾
dos2unix {{文件名}}
# 使用 Unix 样式的行尾创建副本
dos2unix {{[-n|--newfile]}} {{文件名}} {{文件名}}

# 运行 glow 并选择文件查看
glow
# 渲染 Markdown 文件到终端
glow {{路径/到/文件}}
# 使用分页器查看 Markdown 文件
glow {{[-p|--pager]}} {{路径/到/文件}}
# 从 URL 查看文件
glow {{https://example.com/file.md}}

# 在文件中查找模式
grep "{{模式字符串}}" {{路径/到/文件1 路径/到/文件2}}
# 查找精确的字符串（禁用 `regex` 式）
grep {{[-F|--fixed-strings]}} "{{字符串}}" {{路径/到/文件}}
# 在目录中递归查找所有文件中的模式，忽略二进制文件
grep {{[-rI|--recursive --binary-files=without-match]}} "{{模式字符串}}" {{路径/到/目录}}
# 打印每个匹配项周围、之前或之后的 3 行上下文
grep {{--context|--before-context|--after-context}} 3 "{{模式字符串}}" {{路径/到/文件}}

# 输出文件的前几行
head {{[-n|--lines]}} {{数目}} {{路径/到/文件}}
# 输出文件的前几个字节
head {{[-c|--bytes]}} {{数目}} {{路径/到/文件}}
# 输出文件除最后几行之外的所有内容
head {{[-n|--lines]}} -{{数目}} {{路径/到/文件}}
# 输出文件除最后几个字节之外的所有内容
head {{[-c|--bytes]}} -{{数目}} {{路径/到/文件}}

# 打印文件的十六进制表示形式，重复的行用 '*' 替代
hexdump {{路径/到/文件}}
# 以十六进制显示输入偏移量，并在最后两列中显示其 ASCII 表示形式
hexdump {{[-C|--canonical]}} {{路径/到/文件}}
# 显示文件的十六进制表示，但只解释输入的指定字节数
hexdump {{[-C|--canonical]}} {{[-n|--length]}} {{字节数}} {{路径/到/文件}}
# 不使用 '*' 替换重复的行
hexdump {{[-v|--no-squeezing]}} {{路径/到/文件}}

# 根据第一个（默认）字段合并两个文件
join {{路径/到/文件1}} {{路径/到/文件2}}
# 使用逗号（而不是空格）作为字段分隔符合并两个文件
join -t ',' {{路径/到/文件1}} {{路径/到/文件2}}
# 将文件 1 的字段 3 与文件 2 的字段 1 合并
join -1 {{3}} -2 {{1}} {{路径/到/文件1}} {{路径/到/文件2}}
# 为文件 1 中的每行未配对的行生成一行
join -a {{1}} {{路径/到/文件1}} {{路径/到/文件2}}

# 打开一个文件
less {{路径/到/文件}}
# 向下/向上翻页
{{<Space>|<b>}}
# 转到文件末尾/开头
{{<G>|<g>}}
# 向前搜索字符串（按 `<n>`/`<N>` 转到下一个/上一个匹配项）
</>{{关键字}}

# 更改文件的行尾
mac2unix {{文件名}}
# 使用 Unix 样式的行尾创建副本
mac2unix {{[-n|--newfile]}} {{文件名}} {{新文件名}}

# 漂亮地打印一个或多个规范格式的图形
nop {{路径/到/输入1.gv 路径/到/输入2.gv ...}} >{{路径/到/输出.gv}}
# 检查一个或多个图形的有效性，不生成输出图形
nop -p {{路径/到/输入1.gv 路径/到/输入2.gv ...}}
# 显示帮助
nop -?

# 将所有行合并为一行，使用 tab 作为分隔符
paste {{[-s|--serial]}} {{路径/到/文件}}
# 使用指定的分隔符将所有行合并为一行
paste {{[-s|--serial]}} {{[-d|--delimiters]}} {{分隔符}} {{路径/到/文件}}
# 并排合并两个文件，每个文件以 tab 分隔为单独的列
paste {{路径/到/文件1}} {{路径/到/文件2}}
# 并排合并两个文件，每个文件以指定的分隔符分隔为单独的列
paste {{[-d|--delimiters]}} {{分隔符}} {{路径/到/文件1}} {{路径/到/文件2}}

# 在 PDF 中查找与关键词匹配的行
pdfgrep {{关键词}} {{文件.pdf}}
# 包含每个匹配行的文件名和页码
pdfgrep {{[-H|--with-filename]}} {{[-n|--page-number]}} {{关键词}} {{文件.pdf}}
# 对以 "foo" 开头关键词搜索，返回前 3 个匹配项，不区分大小写
pdfgrep {{[-m|--max-count]}} 3 {{[-i|--ignore-case]}} '{{^foo}}' {{文件.pdf}}
# 在当前目录中扩展名为.pdf 的文件中递归查找关键词
pdfgrep {{[-r|--recursive]}} {{关键词}}

# 显示所有环境变量的键值对
printenv
# 显示特定变量的值
printenv {{HOME}}
# 显示变量的值并以 NUL 而不是换行符结尾
printenv {{[-0|--null]}} {{HOME}}

# 从 `.proto` 文件生成 Python 代码
protoc --python_out={{路径/到/输出目录}} {{输入文件.proto}}
# 从一个导入其他 `.proto` 文件的 `.proto` 文件生成 Java 代码
protoc --java_out={{路径/到/输出目录}} --proto_path={{路径/到/导入搜索路径}} {{输入文件.proto}}
# 生成多种语言的代码
protoc --csharp_out={{路径/到/c#_输出目录}} --js_out={{路径/到/js_输出目录}} {{输入文件.proto}}
# 从 `.proto` 文件将文本格式消息编码为协议消息
protoc <{{消息.txt}} --encode={{类型名称}} {{输入文件.proto}}

# 在当前目录中递归搜索匹配模式的内容（`regex`）
rg {{模式}}
# 在指定文件或目录中递归搜索匹配模式的内容
rg {{模式}} {{路径/到/文件或目录}}
# 搜索字面字符串模式
rg {{[-F|--fixed-strings]}} -- {{字符串}}
# 包含隐藏文件以及 `.gitignore` 中列出的条目
rg {{[-.|--hidden]}} --no-ignore {{模式}}

# 以升序对文件进行排序
sort {{路径/到/文件}}
# 以降序对文件进行排序
sort {{[-r|--reverse]}} {{路径/到/文件}}
# 以不区分大小写的方式对文件进行排序
sort {{[-f|--ignore-case]}} {{路径/到/文件}}
# 用数字而不是字母顺序对文件进行排序
sort {{[-n|--numeric-sort]}} {{路径/到/文件}}

# 显示文件中最后 n 行
tail {{[-n|--lines]}} {{n}} {{路径/到/文件}}
# 从特定行号开始打印文件后续内容
tail {{[-n|--lines]}} +{{行号}} {{路径/到/文件}}
# 从给定文件末尾打印特定字节数量的内容
tail {{[-n|--lines]}} {{字节数}} {{路径/到/文件}}
# 打印给定文件的最后几行并保持读取直到 `<Ctrl c>`
tail {{[-f|--follow]}} {{路径/到/文件}}

# 在适用的情况下用下划线显示文件的内容
ul {{文件路径}}
# 用由破折号组成的下划线显示文件的内容 `-`
ul {{[-i|--indicated]}} {{文件路径}}

# 仅显示每行一次
sort {{路径/到/文件}} | uniq
# 仅显示唯一的行
sort {{路径/到/文件}} | uniq {{[-u|--unique]}}
# 仅显示重复的行
sort {{路径/到/文件}} | uniq {{[-d|--repeated]}}
# 显示每行的出现次数及其内容
sort {{路径/到/文件}} | uniq {{[-c|--count]}}

# 更改文件的行尾
unix2dos {{文件名}}
# 使用 DOS 样式的行尾创建副本
unix2dos {{[-n|--newfile]}} {{文件名}} {{新文件名}}

# 更改文件的行尾
unix2mac {{文件名}}
# 使用 macOS 样式的行尾创建副本
unix2mac {{[-n|--newfile]}} {{文件名}} {{新文件名}}

# 计数文件中的行数
wc {{[-l|--lines]}} {{路径/到/文件}}
# 计数文件中的单词数
wc {{[-w|--words]}} {{路径/到/文件}}
# 计数文件中的字节数
wc {{[-c|--bytes]}} {{路径/到/文件}}
# 计数文件中的字符数（考虑所有多字节的字符）
wc {{[-m|--chars]}} {{路径/到/文件}}

# 创建一个包含 C 语言解析器代码的文件 `y.tab.c`，并编译语法文件以及所有值所需的常量声明。（只有在使用 `-d` 选项时，才会创建常量声明文件 `y.tab.h`）
yacc -d {{路径/到/grammar_file.y}}
# 编译一个包含解析器描述的语法文件，以及报告由于语法中的歧义导致的冲突
yacc -d {{路径/到/grammar_file.y}} -v
# 编译一个语法文件，并用 `prefix` 代替 `y` 作为输出文件名前缀
yacc -d {{路径/到/grammar_file.y}} -v -b {{前缀}}

# 通过 USB 或 NFC 启用某个应用程序（`--enable` 可以多次使用以指定更多应用程序）
ykman config {{usb|nfc}} {{[-e|--enable]}} {{otp|u2f|fido2|oath|piv|openpgp|hsmauth}}
# 通过 USB 或 NFC 禁用某个应用程序（`--disable` 可以多次使用以指定更多应用程序）
ykman config {{usb|nfc}} {{[-d|--disable]}} {{otp|u2f|fido2|oath|piv|openpgp|hsmauth}}
# 禁用 NFC 上的所有应用程序
ykman config nfc {{[-D|--disable-all]}}

# 以漂亮打印格式输出 YAML 文件（v4+）
yq eval {{路径/到/file.yaml}}
# 以漂亮打印格式输出 YAML 文件（v3）
yq read {{路径/到/file.yaml}} {{[-C|--colors]}}
# 输出仅包含数组的 YAML 文件中的第一个元素（v4+）
yq eval '.[0]' {{路径/到/file.yaml}}
# 输出仅包含数组的 YAML 文件中的第一个元素（v3）
yq read {{路径/到/file.yaml}} '[0]'

# 比较文件
diff3 {{路径/到/文件1}} {{路径/到/文件2}} {{路径/到/文件3}}
# 展示所有的变化，同时列出冲突
diff3 {{[-A|--show-all]}} {{路径/到/文件1}} {{路径/到/文件2}} {{路径/到/文件3}}

# 以交互模式启动
qalc {{[-i|--interactive]}}
# 以简洁模式启动（仅输出结果）
qalc {{[-t|--terse]}}
# 更新货币兑换率
qalc {{[-e|--exrates]}}
# 非交互地执行计算
qalc {{66+99|2^4|6 feet to cm|1 bitcoin to USD|20 kmph to mph|...}}

perm.example:
# 创建一个新用户，在默认路径创建 home 目录，并提示用户设置密码
adduser {{用户名}}
# 创建一个新用户，不生成 home 目录
adduser --no-create-home {{用户名}}
# 创建一个新用户，并在指定路径下创建 home 目录
adduser --home {{home 路径}} {{用户名}}
# 创建一个新用户，并指定登录 shell
adduser --shell {{shell 路径}} {{用户名}}

# 授予所有者［u］执行［x］文件的权限
chmod u+x {{文件}}
# 授予所有者［u］读［r］和写［w］文件或目录的权限
chmod u+rw {{文件或目录}}
# 移除用户组［g］的文件执行［x］权限
chmod g-x {{文件}}
# 授予所有用户［a］读［r］以及执行［x］文件的权限
chmod a+rx {{文件}}

# 修改文件或目录的所有者
chown {{用户}} {{路径/到/文件或目录}}
# 修改文件或目录的所有者及所属组
chown {{用户}}:{{用户组}} {{路径/到/文件或目录}}
# 将所有者用户和用户组都更改为 `user`
chown {{user}}: {{路径/到/文件_或_目录}}
# 递归修改目录及其子目录和文件的所有者
chown {{[-R|--recursive]}} {{用户}} {{路径/到/目录}}

# 删除用户
sudo deluser {{用户名}}
# 删除用户及其主目录
sudo deluser --remove-home {{用户名}}
# 删除用户及其主目录，但将其文件备份到指定目录中的 `.tar.gz` 文件
sudo deluser --backup-to {{路径/到/备份目录}} --remove-home {{用户名}}
# 删除用户及其所有拥有的文件
sudo deluser --remove-all-files {{用户名}}

# 以超级用户身份运行命令
sudo {{less /var/log/syslog}}
# 以超级用户身份使用默认编辑器编辑文件
sudo {{[-e|--edit]}} {{/etc/fstab}}
# 以其他用户和(或)组的身份运行命令
sudo {{[-u|--user]}} {{用户}} {{[-g|--group]}} {{组}} {{id -a}}
# 重复执行上一条以`sudo`为前缀的命令（仅适用于 Bash、Zsh 等）
sudo !!

# 显示所有当前已登录用户的信息
w
# 显示指定用户的信息
w {{用户名}}
# 显示已登录用户信息，但不显示标题行
w {{[-h|--no-header]}}
# 显示信息时不包含登录时间、JCPU 和 PCPU 列
w {{[-s|--short]}}

# 显示用户名，终端线路，和所有当前登录会话的时间
who
# 显示所有可用信息
who {{[-a|--all]}}
# 显示所有可用信息，包含表格首部名称
who {{[-aH|--all --heading]}}

# 新建用户并创建家目录
sudo useradd -m {{用户名}}
# 指定 shell 与附加组
sudo useradd -m -s /bin/bash -G {{docker}} {{用户名}}
# 查看用户是否已创建
getent passwd {{用户名}}

# 把用户追加到附加组（-a 必须与 -G 配合）
sudo usermod -aG {{组名}} {{用户名}}
# 修改登录 shell
sudo usermod -s /bin/zsh {{用户名}}
# 锁定 / 解锁账号
sudo usermod -L {{用户名}}
sudo usermod -U {{用户名}}

# 修改当前用户密码
passwd
# 重置指定用户密码（需要 root）
sudo passwd {{用户名}}
# 锁定账号密码
sudo passwd -l {{用户名}}
# 查看密码状态
sudo passwd -S {{用户名}}

# 新建用户组
sudo groupadd {{组名}}
# 指定 GID 新建组
sudo groupadd -g {{1000}} {{组名}}
# 查看已有组
getent group

# 修改单个文件的属组
sudo chgrp {{组名}} {{路径/到/文件}}
# 递归修改目录及内容属组
sudo chgrp -R {{组名}} {{路径/到/目录}}
# 同时属主与属组
sudo chown {{用户}}:{{组名}} {{路径/到/文件}}

# 列出用户的密码信息
chage {{[-l|--list]}} {{用户名}}
# 启用密码在 10 天内过期
sudo chage {{[-M|--maxdays]}} 10 {{用户名}}
# 关闭密码过期
sudo chage {{[-M|--maxdays]}} -1 {{用户名}}
# 设置账户到期日期
sudo chage {{[-E|--expiredate]}} {{YYYY-MM-DD}} {{用户名}}

proc.example:
# 禁用配置文件
sudo a2disconf {{配置文件}}
# 不显示信息性消息
sudo a2disconf {{[-q|--quiet]}} {{配置文件}}

# 禁用模块
sudo a2dismod {{模块路径}}
# 不显示信息性消息
sudo a2dismod {{[-q|--quiet]}} {{模块路径}}

# 禁用虚拟主机
sudo a2dissite {{虚拟主机名}}
# 不显示信息性消息
sudo a2dissite {{[-q|--quiet]}} {{虚拟主机名}}

# 启用配置文件
sudo a2enconf {{配置文件}}
# 不显示信息性消息
sudo a2enconf {{[-q|--quiet]}} {{配置文件}}

# 启用模块
sudo a2enmod {{模块名}}
# 不显示信息性消息
sudo a2enmod {{[-q|--quiet]}} {{模块名}}

# 启用虚拟主机
sudo a2ensite {{虚拟主机名}}
# 不显示信息性消息
sudo a2ensite {{[-q|--quiet]}} {{虚拟主机名}}

# 启动守护进程
bluetoothd
# 启动守护进程，日志输出到标准输出
bluetoothd {{[-n|--nodetach]}}
# 指定一个配置文件启动守护进程（默认是 `/etc/bluetooth/main.conf`）
bluetoothd {{[-f|--configfile]}} {{配置文件}}
# 启动守护进程并将详细信息输出到标准错误
bluetoothd {{[-d|--debug]}}

# 显示当前月份的日历
cal
# 显示上个月、当前月和下个月
cal {{[-3|--three]}}
# 使用星期一作为一周的第一天
cal {{[-m|--monday]}}
# 显示特定年份的日历（4 位数字）
cal {{年份}}

# 在终端中运行
glances
# 以网页服务器模式运行，在浏览器中查看结果
glances {{[-w|--webserver]}}
# 以服务器模式启动，允许其他 glances 客户端连接以查看数据
glances {{[-s|--server]}}
# 作为客户端连接到 glances 服务器
glances {{[-c|--client]}} {{主机名}}

# 运行 Python web 应用程序
gunicorn {{导入路径：应用程序}}
# 在 localhost 上监听 8080 端口
gunicorn {{[-b|--bind]}} localhost:8080 {{导入路径：应用程序}}
# 启用实时自动加载
gunicorn --reload {{导入路径：应用程序}}
# 使用 4 个工作进程处理请求
gunicorn {{[-w|--workers]}} 4 {{导入路径：应用程序}}

# 显示本机的主机名
hostname
# 显示主机名的网络地址
hostname {{[-i|--ip-address]}}
# 显示 FQDN（完全限定域名）
hostname {{[-f|--fqdn]}}
# 设置本机主机名
hostname {{新主机名}}

# 启动 `htop`
htop
# 启动 `htop`, 显示指定用户拥有的进程
htop {{[-u|--user]}} {{用户名}}
# 以树形视图显示进程的层级关系，展示父子进程之间的关系
htop {{[-t|--tree]}}
# 使用指定的 `sort_item` 对进程排序（使用 `htop --sort help` 获取可用选项）
htop {{[-s|--sort]}} {{sort_item}}

# 打印 Java 进程的共享对象映射（类似 pmap 的输出）
jmap {{Java 进程号}}
# 打印堆摘要信息
jmap -heap {{文件名.jar}} {{Java 进程号}}
# 按类型打印堆使用的直方图
jmap -histo {{Java 进程号}}
# 将堆的内容转储到二进制文件中以使用 jhat 进行分析
jmap -dump:format=b,file={{路径/到/文件}} {{Java 进程号}}

# 从 JSON 或 JSON Lines 输入中打印表格
cat {{文件.json}} | jtbl
# 打印表格并指定用于换行的列宽
cat {{文件.json}} | jtbl --cols={{宽度}}
# 打印表格并截断行而不是换行
cat {{文件.json}} | jtbl {{[-t|--truncate]}}
# 打印表格并不换行或截断行
cat {{文件.json}} | jtbl {{[-n|--no-wrap]}}

# 使用默认的 `SIGTERM`（终止）信号来结束一个程序
kill {{进程id}}
# 列出可用的信号名称（使用时无需加 `SIG` 前缀）
kill -l
# 使用 `SIGHUP`（挂起）信号终止一个程序。许多守护进程接收到此信号后会重新加载而不是终止
kill {{[-1|-SIGHUP]}} {{进程id}}
# 使用 `SIGINT`（中断）信号终止一个程序。通常由用户按下 `<Ctrl c>` 发起
kill {{[-2|-SIGINT]}} {{进程id}}

# 使用默认的 `SIGTERM`（终止）信号结束进程
killall {{进程名称}}
# 列出可用的信号名称（使用时无需加 `SIG` 前缀）
killall {{[-l|--list]}}
# 交互式地询问确认后再终止进程
killall {{[-i|--interactive]}} {{进程名称}}
# 使用 `SIGINT`（中断）信号终止进程，与按下 `<Ctrl c>` 发送的信号相同
killall {{[-2|-SIGINT]}} {{进程名称}}

# 使用指定的参数执行命令并将其输出保存到日志文件中
logsave {{path/to/logfile}} {{command}}
# 从标准输入中获取输入并将其保存在日志文件中
logsave {{logfile}} -
# 将输出追加到日志文件，而不是替换其当前内容
logsave -a {{logfile}} {{command}}
# 显示详细输出
logsave -v {{logfile}} {{command}}

# 查找打开了给定文件的进程
lsof {{路径/到/文件}}
# 查找打开了本地互联网端口的进程
lsof -i :{{端口}}
# 仅输出进程 ID (PID)
lsof -t {{路径/到/文件}}
# 列出给定用户打开的文件
lsof -u {{用户名}}

# 指定存储目录（默认：Linux 和 macOS 为 `/data/db`，Windows 为 `C:\data\db`）
mongod --dbpath {{路径/到/目录}}
# 指定配置文件
mongod --config {{路径/到/文件}}
# 指定监听的端口（默认：27017）
mongod --port {{端口}}
# 指定数据库分析级别。0 为关闭，1 仅慢操作，2 所有（默认：0）
mongod --profile {{0|1|2}}

# 显示系统信息
neofetch
# 在输出中显示或隐藏指定的信息行，'信息名称'是配置文件中的函数名称，例如 memory
neofetch --{{enable|disable}} {{信息名称}}
# 隐藏或显示操作系统架构信息
neofetch --os_arch {{on|off}}
# 启用或禁用输出中的 CPU 品牌信息
neofetch --cpu_brand {{on|off}}

# 返回命令字符串匹配的所有正在运行进程的 PID
pgrep {{进程名称}}
# 同时显示完整命令
pgrep {{[-a|--list-full]}} {{进程名称}}
# 搜索进程时包含其命令行选项
pgrep {{[-f|--full]}} "{{进程名称}} {{参数}}"
# 搜索由特定用户运行的进程
pgrep {{[-u|--euid]}} {{用户名}} {{进程名称}}

# 创建一个新项目
quarto create-project {{路径/到/目录}} --type {{book|default|website}}
# 创建一个新的博客网站
quarto create-project {{路径/到/目录}} --type {{website}} --template {{blog}}
# 将输入文件渲染为不同格式
quarto render {{路径/到/文件.ext}} --to {{html|pdf|docx}}
# 渲染并预览文档或网站
quarto preview {{路径/到/目录 | 路径/到/文件}}

# 启动交互式菜单来配置 rclone
rclone config
# 列出 rclone 远程目录的内容
rclone lsf {{远程名}}:{{路径/到/目录}}
# 将文件或目录从本地计算机复制到远程目标
rclone copy {{路径/到/本地文件或目录}} {{远程名}}:{{路径/到/目录}}
# 将过去 24 小时内修改过的文件从本地复制到远程，并向用户逐个文件确认
rclone copy {{[-i|--interactive]}} --max-age 24h {{远程名}}:{{路径/到/目录}} {{路径/到/本地目录}}

# 以当前用户身份启动 runit 服务
runsv {{路径/到/服务目录}}
# 以 root 用户身份启动 runit 服务
sudo runsv {{路径/到/服务目录}}

# 以当前用户身份启动和管理目录中的所有服务
runsvdir {{路径/到/服务目录}}
# 以 root 用户身份启动和管理目录中的所有服务
sudo runsvdir {{路径/到/服务目录}}
# 在单独会话中启动服务
runsvdir -P {{路径/到/服务目录}}

# 使用指定路径启动 `spf`
spf {{path/to/directory}}
# 使用多个路径启动 `spf`
spf {{path/to/directory1 path/to/directory2 ...}}
# 修复快捷键设置，补全缺失的按键
spf {{[--fh|--fix-hotkeys]}}
# 修复配置文件，补全缺失的项
spf {{[--fch|--fix-config-file]}}

# 启动服务
sudo sv up {{路径/到/服务目录}}
# 停止服务
sudo sv down {{路径/到/服务目录}}
# 获取服务状态
sudo sv status {{路径/到/服务目录}}
# 重载服务
sudo sv reload {{路径/到/服务目录}}

# 启动一个新会话
tmux
# 启动一个指定名称的新会话（[s]ession）
tmux {{[new|new-session]}} -s {{name}}
# 列出现有会话
tmux {{[ls|list-sessions]}}
# 连接到最近使用的会话
tmux {{[a|attach]}}

# 打印内核名称
uname
# 打印所有可用的系统信息
uname {{[-a|--all]}}
# 打印系统架构和处理器信息
uname {{[-mp|--machine --processor]}}
# 打印内核名称、内核版本号和内核版本
uname {{[-srv|--kernel-name --kernel-release --kernel-version]}}

# 打印当前时间，运行时间，登录用户数量和其他信息
uptime
# 仅显示系统已启动的时间长度
uptime {{[-p|--pretty]}}
# 打印系统启动的日期和时间
uptime {{[-s|--since]}}
# 显示版本信息
uptime {{[-V|--version]}}

# 运行 Python Web 应用
uvicorn {{导入路径:应用对象}}
# 在本地主机上监听端口 8080
uvicorn --host localhost --port 8080 {{导入路径:应用对象}}
# 启用实时重新加载
uvicorn --reload {{导入路径:应用对象}}
# 使用 4 个工作进程处理请求
uvicorn --workers 4 {{导入路径:应用对象}}

# 使用默认配置文件启动代理
zabbix_agent2
# 使用自定义配置文件启动代理
zabbix_agent2 {{[-c|--config]}} {{路径/到/zabbix_agent2.conf}}
# 测试配置文件并退出
zabbix_agent2 {{[-c|--config]}} {{路径/到/zabbix_agent2.conf}} {{[-T|--test-config]}}
# 测试指定监控项并输出详细信息
zabbix_agent2 {{[-c|--config]}} {{路径/到/zabbix_agent2.conf}} {{[-t|--test]}} {{监控项键值}} {{[-v|--verbose]}}

# 使用默认配置文件启动 agent
zabbix_agentd
# 使用自定义配置文件启动 agent
zabbix_agentd {{[-c|--config]}} {{路径/到/zabbix_agentd.conf}}
# 在前台运行 agent（保持附着在当前终端会话中）
zabbix_agentd {{[-c|--config]}} {{路径/到/zabbix_agentd.conf}} {{[-f|--foreground]}}
# 测试配置文件
zabbix_agentd {{[-c|--config]}} {{路径/到/zabbix_agentd.conf}} {{[-T|--test-config]}}

# 使用默认配置文件启动服务器
zabbix_server
# 使用自定义配置文件启动服务器
zabbix_server {{[-c|--config]}} {{路径/到/zabbix_server.conf}}
# 在前台运行服务器
zabbix_server {{[-c|--config]}} {{路径/到/zabbix_server.conf}} {{[-f|--foreground]}}
# 测试配置文件并退出
zabbix_server {{[-c|--config]}} {{路径/到/zabbix_server.conf}} {{[-T|--test-config]}}

# 启动一个新的命名会话
zellij {{[-s|--session]}} {{名称}}
# 列出现有会话
zellij {{[ls|list-sessions]}}
# 附加到最近使用的会话
zellij {{[a|attach]}}
# 打开一个新窗格（在 zellij 会话中）
<Alt n>

# 显示电池信息
acpi
# 显示热量（温度）信息
acpi {{[-t|--thermal]}}
# 显示冷却设备信息
acpi {{[-c|--cooling]}}
# 用华氏度单位显示热量（温度）信息
acpi {{[-tf|--thermal --fahrenheit]}}

# 报告整个系统的错误
apport-bug
# 报告某个软件包的错误
apport-bug {{包名}}
# 报告某个可执行文件的错误
apport-bug {{可执行文件路径}}
# 报告某个进程的错误
apport-bug {{pid}}

# 在新的根目录下开启一个交互外壳程序（默认是 Bash）
arch-chroot {{新根目录}}
# 指定除当前用户外的其他用户来运行外壳程序
arch-chroot -u {{用户名}} {{新根目录}}
# 在新的根目录下运行一个自定义命令（取代默认的 Bash）
arch-chroot {{新根目录}} {{命令}} {{命令参数}}
# 指定除默认的 Bash 以外的外壳程序（以下例子需要现在目标系统中先安装 `zsh`）
arch-chroot {{新根目录}} {{zsh}}

# 以新的根目录，运行命令
sudo chroot {{路径/到/新/根目录}} {{命令}}
# 使用指定的用户和组
sudo chroot --userspec {{用户名或用户id:组名或组id}}

# 显示所有 CPU 的信息
cpuid
# 仅显示当前 CPU 的信息
cpuid {{[-1|--one-cpu]}}
# 显示原始十六进制信息，不进行解码
cpuid {{[-r|--raw]}}

# 分析堆转储文件（来自 jmap），通过 HTTP 端口 7000 进行查看
jhat {{路径/堆转储文件}}
# 分析堆转储文件，为 HTTP 服务指定备用端口
jhat {{[-p|-port]}} {{端口}} {{路径/堆转储文件}}
# 通过 jhat 分析转储文件，指定使用 8 GB RAM（建议使用 2-4 倍的转储大小）
jhat -J-mx8G {{路径/堆转储文件}}

# 打印 Java 进程中所有线程的 Java 栈跟踪
jstack {{java_进程号}}
# 打印混合模式（Java/C++）的栈跟踪
jstack -m {{java_进程号}}
# 打印来自 Java 核心转储的栈跟踪
jstack {{/usr/bin/java}} {{文件.core}}

# 显示所有 CPU 信息
lscpu
# 以表格方式显示信息
lscpu {{[-e|--extended]}}
# 仅显示表中离线 CPU 的信息
lscpu {{[-e|--extended]}} {{[-c|--offline]}}

# 显示逻辑卷信息
sudo lvs
# 显示所有逻辑卷
sudo lvs {{[-a|--all]}}
# 改变默认显示以显示更多细节
sudo lvs {{[-v|--verbose]}}
# 只显示特定字段
sudo lvs {{[-o|--options]}} {{域名 1,域名 2,...}}

# 假装将模块加载到内核中，但实际上不这样做
modprobe {{[-n|--dry-run]}} {{模块名}}
# 加载模块到内核
sudo modprobe {{模块名}}
# 从内核移除模块
sudo modprobe {{[-r|--remove]}} {{模块名}}
# 从内核移除模块及所有依赖它的模块
sudo modprobe {{[-r|--remove]}} --remove-holders {{模块名}}

# 列出全部已加载模块
lsmod
# 过滤指定模块
lsmod | grep {{模块名}}
# 查看某模块详情
modinfo {{模块名}}

# 跟踪一条命令的全部系统调用
strace {{命令}}
# 附加到正在运行的进程（需要 root）
sudo strace -p {{PID}}
# 只跟踪文件相关调用
strace -e trace=openat {{命令}}
# 统计各系统调用耗时与次数
strace -c {{命令}}

# 每 2 秒执行一次命令并刷新
watch -n {{2}} {{命令}}
# 高亮输出中的变化部分
watch -d {{命令}}
# 监控指定进程
watch -n 1 'ps aux | grep {{进程名}}'

# 查看当前用户身份
id
# 查看指定用户身份
id {{用户名}}
# 只显示用户组
id -g -n {{用户名}}

# 查看最近 10 条登录记录
last -n {{10}}
# 查看指定用户的登录记录
last {{用户名}}
# 查看系统重启记录
last reboot

net.example:
# 向目标 URL 执行 100 次 HTTP GET 请求
ab -n 100 {{url}}
# 使用 10 个并发请求，同时向目标 URL 执行 100 次 HTTP GET 请求
ab -n 100 -c 10 {{url}}
# 使用来自文件的 JSON 负载对 URL 执行 100 个 HTTP POST 请求
ab -n 100 -T {{application/json}} -p {{path/to/file.json}} {{url}}
# 使用 HTTP [K]eep Alive，即在一个 HTTP 会话中执行多个请求
ab -k {{url}}

# 以小时为单位打印当前用户连接时间
ac
# 以小时为单位打印所有用户连接时间
ac {{[-p|--individual-totals]}}
# 以小时为单位打印特定用户连接时间
ac {{[-p|--individual-totals]}} {{用户名}}
# 以小时为单位打印特定用户每天连接时间
ac {{[-d|--daily-totals]}} {{[-p|--individual-totals]}} {{用户名}}

# 运行并生成一个私钥和证书
agate --content {{路径/到/内容}}/ --addr {{[::]:1965}} --addr {{0.0.0.0:1965}} --hostname {{example.com}} --lang {{en-US}}
# 启动服务器
agate {{路径/到/目录}}
# 显示帮助
agate {{[-h|--help]}}

# 打开特定文件或目录
agy {{路径/到/文件或目录}}
# 比较两个文件
agy {{[-d|--diff]}} {{路径/到/文件1}} {{路径/到/文件2}}
# 传入提示词来运行一个在当前工作目录的聊天会话
agy chat "{{提示词}}"
# 安装或卸载特定扩展
agy --{{install|uninstall}}-extension {{发布者.扩展|路径/到/扩展.vsix}}

# 使用字典文件破解捕获文件中的密钥
aircrack-ng -w {{路径/到/字典文件.txt}} {{路径/到/捕获文件.cap}}
# 使用多线程和字典文件破解捕获文件中的密钥
aircrack-ng -p {{线程数}} -w {{路径/到/字典文件.txt}} {{路径/到/捕获文件.cap}}
# 使用字典文件和接入点的 ESSID 破解捕获文件中的密钥
aircrack-ng -w {{路径/到/字典文件.txt}} -e {{extended_ssid}} {{路径/到/捕获文件.cap}}
# 使用字典文件和接入点的 MAC 地址破解捕获文件中的密钥
aircrack-ng -w {{路径/到/字典文件.txt}} --bssid {{mac}} {{路径/到/捕获文件.cap}}

# 从开放网络捕获文件中移除无线头，并使用接入点的 MAC 地址进行过滤
airdecap-ng -b {{ap_mac}} {{路径/到/捕获文件.cap}}
# 使用十六进制格式的密钥解密 WEP 加密的捕获文件
airdecap-ng -w {{hex_key}} {{路径/到/捕获文件.cap}}
# 使用接入点的 ESSID 和密码解密 WPA/WPA2 加密的捕获文件
airdecap-ng -e {{extended_ssid}} -p {{密码}} {{路径/到/捕获文件.cap}}
# 使用接入点的 ESSID 和密码解密 WPA/WPA2 加密的捕获文件，并保留头部信息
airdecap-ng -l -e {{extended_ssid}} -p {{密码}} {{路径/到/捕获文件.cap}}

# 共享文件或目录
airshare {{code}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}
# 接收文件
airshare {{code}}
# 主机接收服务器（使用此选项可以通过 Web 接口上传文件）
airshare --upload {{code}}
# 将文件或目录发送到接收服务器
airshare --upload {{code}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}

# 显示当前的 ARP 表
arp -a
# 删除特定条目
arp -d {{地址}}
# 创建指定条目
arp -s {{地址}} {{MAC 地址}}

# 扫描当前本地网络
arp-scan {{[-l|--localnet]}}
# 扫描带有自定义位掩码的 IP 网络
arp-scan {{192.168.1.1}}/{{24}}
# 扫描自定义范围内的 IP 网络
arp-scan {{127.0.0.0}}-{{127.0.0.31}}
# 扫描带有自定义子网掩码的 IP 网络
arp-scan {{10.0.0.0}}:{{255.255.255.0}}

# 链接下载
axel {{超链接}}
# 链接下载，指定文件名
axel {{超链接}} {{[-o|--output]}} {{路径/到/文件}}
# 多连接数下载
axel {{[-n|--num-connections]}} {{连接数量}} {{超链接}}
# 查询镜像
axel {{[-S|--search=]}}{{镜像数量}} {{超链接}}

# 使用特定配置文件启动 Bird
bird -c {{路径/到/bird.conf}}
# 以特定用户和组身份启动 Bird
bird -u {{用户名}} -g {{组}}

# 显示所有接口的列表
bmon {{[-a|--show-all]}}
# 以每秒位数显示数据传输速率
bmon {{[-b|--use-bit]}}
# 设置策略以定义显示哪些网络接口
bmon {{[-p|--policy]}} {{interface_1,interface_2,interface_3}}
# 设置计算每个计数器速率的间隔（以秒为单位）
bmon {{[-R|--rate-interval]}} {{2.0}}

# 启动 `btop`
btop
# 使用指定预设启动 `btop`
btop {{[-p|--preset]}} {{0..9}}
# 使用 16 种颜色和 TTY 友好的图形符号在 TTY 模式下启动 `btop`
btop {{[-t|--tty]}}
# 在 256 色模式而不是 24 位颜色模式下启动 `btop`
btop {{[-l|--low-color]}}

# 发起 HTTP GET 请求，将响应内容输出到 `stdout`
curl {{https://example.com}}
# 发起 HTTP GET 请求，自动跟随所有 `3xx` 重定向，将响应头和内容输出到 `stdout`
curl {{[-L|--location]}} {{[-D|--dump-header]}} - {{https://example.com}}
# 按照 URL 指定的文件名保存下载内容
curl {{[-O|--remote-name]}} {{https://example.com/filename.zip}}
# 以表单编码格式发送数据（`application/x-www-form-urlencoded` 类型的 POST 请求）。如需从 `stdin` 读取数据，可使用 `--data @file_name` 或 `--data @'-'`
curl {{[-X|--request]}} POST {{[-d|--data]}} '{{name=bob}}' {{http://example.com/form}}

# 使用默认配置文件（当前目录下的 `frpc.ini`）启动服务
frpc
# 使用新的 TOML 配置文件启动服务
frpc {{[-c|--config]}} {{路径/到/frpc.toml}}
# 使用指定的配置文件启动服务
frpc {{[-c|--config]}} {{路径/到/文件}}
# 检查配置文件的有效性
frpc verify {{[-c|--config]}} {{路径/到/文件}}

# 使用默认配置文件启动服务（假定当前目录中存在 `frps.ini`）
frps
# 使用新的 TOML 配置文件启动服务
frps {{[-c|--config]}} {{路径/到/frps.toml}}
# 使用指定的配置文件启动服务
frps {{[-c|--config]}} {{路径/到/文件}}
# 检查配置文件的有效性
frps verify {{[-c|--config]}} {{路径/到/文件}}

# 查询域名的 A、AAAA 和 MX 记录
host {{域名}}
# 查询域名的特定类型记录（CNAME、TXT 等）
host -t {{记录类型}} {{域名}}
# 对 IP 地址执行反向查询
host {{IP地址}}
# 指定备用 DNS 服务器进行查询
host {{域名}} {{8.8.8.8}}

# 列出带有详细信息的接口
ip {{[a|address]}}
# 列出带有简要网络层信息的接口
ip {{[-br|-brief]}} {{[a|address]}}
# 列出带有简要链路层信息的接口
ip {{[-br|-brief]}} {{[l|link]}}
# 显示路由表
ip {{[r|route]}}

# 列出所有端口
netstat {{[-a|--all]}}
# 列出所有被监听端口
netstat {{[-l|--listening]}}
# 列出监听的 TCP 端口
netstat {{[-t|--tcp]}}
# 显示 PID 和程序名
netstat {{[-p|--program]}}

# 使用不同的详细（[v]erbosity）级别扫描远程主机的前 1000 个端口
nmap -v{{1|2|3}} {{ip或主机名}}
# 对整个子网或单个主机进行非常激进的 ping 扫描
nmap -T5 -sn {{192.168.0.0/24|ip或主机名1,ip或主机名2,...}}
# 对来自文件的主机启用操作系统检测、版本检测、脚本扫描和路由跟踪
sudo nmap -A -iL {{路径/到/文件.txt}}
# 扫描特定的端口列表（使用 `-p-` 扫描从 1 到 65535 的所有端口）
nmap -p {{端口1,端口2,...}} {{ip或主机名1,ip或主机名2,...}}

# 使用系统默认名称服务器查询域名的 IP 地址（A 记录）
nslookup {{example.com}}
# 向指定名称服务器查询域名的 NS 记录
nslookup -type=NS {{example.com}} {{8.8.8.8}}
# 查询 IP 地址的反向解析（PTR 记录）
nslookup -type=PTR {{54.240.162.118}}
# 使用 TCP 协议查询任意（ANY）可用记录
nslookup -vc -type=ANY {{example.com}}

# 使用默认波特率 9600 连接到串行控制台
sudo picocom {{/dev/ttyXYZ}}
# 以指定波特率连接到串行控制台
sudo picocom {{/dev/ttyXYZ}} {{[-b|--baud]}} {{波特率}}
# 映射特殊字符（例如：将 `LF` 映射为 `CRLF`）
sudo picocom {{/dev/ttyXYZ}} --imap {{lfcrlf}}
# 退出 picocom
<Ctrl a><Ctrl x>

# Ping 主机
ping {{主机地址}}
# 仅 Ping 主机特定次数
ping -c {{次数}} {{主机地址}}
# Ping 主机，指定请求之间的间隔（以秒为单位）（默认为 1 秒）
ping -i {{间隔秒数}} {{主机地址}}
# Ping 主机而不尝试查找地址的符号名称
ping -n {{主机地址}}

# 列出可用的服务名称
qdbus
# 列出指定服务的对象路径
qdbus {{服务名}}
# 列出指定对象可用的方法、信号和属性
qdbus {{服务名}} /{{路径/到/对象}}
# 执行指定方法，传递参数并显示返回值
qdbus {{服务名}} /{{路径/到/对象}} {{方法名}} {{参数1 参数2 ...}}

# 复制文件
rsync {{路径/到/来源}} {{路径/到/目标}}
# 使用归档模式递归拷贝文件，并保留所有属性，不解析软链接
rsync {{[-a|--archive]}} {{路径/到/来源}} {{路径/到/目标}}
# 将文件以归档模式并保留几乎所有属性进行传输，并以人类可读方式输出详细信息和进度条，中断时保留部分信息
rsync {{[-zvhP|--compress --verbose --human-readable --partial --progress]}} {{路径/到/来源}} {{路径/到/目标}}
# 以递归模式传输文件
rsync {{[-r|--recursive]}} {{路径/到/来源}} {{路径/到/目标}}

# 将本地文件复制到远程主机
scp {{路径/到/本地文件}} {{远程主机地址}}:{{路径/到/远程文件}}
# 连接到远程主机时使用特定端口
scp -P {{端口}} {{路径/到/本地文件}} {{远程主机地址}}:{{路径/到/远程文件}}
# 将文件从远程主机复制到本地目录
scp {{远程主机地址}}:{{路径/到/远程文件}} {{路径/到/本地目录}}
# 递归地将目录内容从远程主机复制到本地目录
scp -r {{远程主机地址}}:{{路径/到/远程目录}} {{路径/到/本地目录}}

# 连接到远程服务器
ssh {{用户名}}@{{远程主机地址}}
# 使用特定身份（私钥）连接到远程服务器
ssh -i {{路径/到/私钥文件}} {{用户名}}@{{远程主机地址}}
# 使用指定端口号连接到远程服务器
ssh {{用户名}}@{{远程主机地址}} -p {{端口号}}
# 在具有伪终端分配的远程服务器上运行命令，允许与远程命令进行交互
ssh {{用户名}}@{{远程主机地址}} -t {{命令}} {{命令参数}}

# 将您的密钥复制到远程主机
ssh-copy-id {{用户名}}@{{远程主机}}
# 将给定的公钥文件复制到远程主机
ssh-copy-id -i {{路径/到/公钥文件}} {{用户名}}@{{远程主机}}
# 将给定的公钥文件通过特定端口复制到远程主机
ssh-copy-id -i {{路径/到/公钥文件}} -p {{端口}} {{用户名}}@{{远程主机}}

# 通过远程 SSH 服务器转发所有 IPv4 TCP 流量
sshuttle {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}}
# 同时将所有 DNS 流量转发到服务器的默认 DNS 解析器
sshuttle --dns {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}}
# 转发所有流量，除了发往特定子网的流量
sshuttle {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}} {{[-x|--exclude]}} {{192.168.0.1/24}}
# 使用 tproxy 方法转发所有 IPv4 和 IPv6 流量
sshuttle --method tproxy {{[-r|--remote]}} {{用户名}}@{{服务器名}} {{0.0.0.0/0}} {{::/0}} {{[-x|--exclude]}} {{你本地 IP 地址}} {{[-x|--exclude]}} {{SSH 服务器的 IP 地址}}

# 列出所有可用的网络接口
tcpdump {{[-D|--list-interfaces]}}
# 捕获特定网络接口的流量
sudo tcpdump {{[-i|--interface]}} {{eth0}}
# 捕获所有 TCP 流量，并在控制台显示其内容（ASCII 编码）
sudo tcpdump -A tcp
# 捕获发往或来自特定主机的流量
sudo tcpdump host {{www.example.com}}

# 为当前目录启动 HTTP 服务器
updog
# 为指定目录启动 HTTP 服务器
updog --directory /{{路径/到/目录}}
# 在指定端口上启动 HTTP 服务器
updog --port {{端口}}
# 使用密码启动 HTTP 服务器（要登录，请将用户名留空，并在密码字段中输入密码）
updog --password {{密码}}

# 将该 URL 的内容下载到文件中（在这个例子中文件名为 "foo"）
wget {{https://example.com/foo}}
# 将该 URL 的内容下载到文件中（在这个例子中文件名为 "bar"）
wget {{[-O|--output-document]}} {{bar}} {{https://example.com/foo}}
# 以每三秒一个请求的速度下载一个网页和其所有资源（脚本，样式表，图片等等）
wget {{[-pkw|--page-requisites --convert-links --wait]}} 3 {{https://example.com/somepage.html}}
# 从一个目录中下载所有列出的文件和其所有子文件夹（不下载内嵌网页）
wget {{[-mnp|--mirror --no-parent]}} {{https://example.com/somepath/}}

# 获取域名信息
whois {{example.com}}
# 获取 IP 地址信息
whois {{8.8.8.8}}
# 获取 IP 地址用于报告滥用的联系方式
whois -b {{8.8.8.8}}

# 使用详细模式 Ping 主机的 80 端口（默认端口）
x tping {{host}}
# Ping 指定主机的特定端口
x tping {{host}}:{{port}}
# 以热力图形式显示结果
x tping {{[-m|--heatmap]}} {{host}}
# 以柱状图形式显示结果
x tping {{[-b|--bar]}} {{host}}:{{port}}

# 打印网络上指定媒体的媒体信息
you-get {{[-i|--info]}} {{https://example.com/video?id=value}}
# 从指定 URL 下载媒体
you-get {{https://example.com/video?id=value}}
# 在 Google 视频上搜索并下载
you-get {{关键词}}
# 将媒体下载到指定位置
you-get {{[-o|--output-dir]}} {{路径/到/目录}} {{[-O|--output-filename]}} {{文件名}} {{https://example.com/watch?v=value}}

# 通过歌曲名称下载（交互式选择）
ytmdl {{歌曲名称}}
# 不提示直接下载第一个结果
ytmdl {{[-q|--quiet]}} {{歌曲名称}}
# 将歌曲下载到指定目录
ytmdl {{[-o|--output-dir]}} {{路径/到/目录}} {{歌曲名称}}
