unison -doc {{主题}}

# ping 指定的主机（省略则默认为 bing.com）
x ping {{host}}
# 以热力图形式显示 ping 结果
x ping {{[-m|--heatmap]}} {{host}}
# 以柱状图形式显示 ping 结果
x ping {{[-b|--bar]}} {{host}}
