tmt run plan {{[-n|--name]}} {{/plan/name}} test {{[-n|--name]}} {{/test/name}}

# 在当前目录中创建一个新的 Python 项目
uv init
# 在具有指定名称的目录中创建一个新的 Python 项目
uv init {{项目名称}}
# 向项目中添加一个新的软件包
uv add {{软件包}}
# 从项目中移除一个软件包
uv remove {{软件包}}

# 全局安装一个模块
yarn global add {{module_name}}
# 安装 `package.json` 中指定的依赖（`install` 命令是可选的 -- 你可以直接输入`yarn`）
yarn install
# 安装一个模块并将其写入 `package.json` 中的依赖项（增加 `--dev` 来作为开发依赖写入）
yarn add {{module_name}}@{{version}}
# 卸载一个模块并将其从 `package.json` 的依赖项中移除
yarn remove {{module_name}}

# 显示所有已挂载 ZFS 存储池的详细配置
zdb
# 显示特定 ZFS 存储池的详细配置
zdb {{[-C|--config]}} {{存储池名称}}
# 显示关于块的数量、大小和重复数据删除的统计信息
zdb {{[-b|--block-stats]}} {{存储池名称}}

# 在 Zed 中打开指定路径
zed {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}
# 在前台打开一个路径并显示日志
zed {{路径/到/项目}} --foreground
# 在新窗口中打开一个路径
zed {{路径/到/项目}} {{[-n|--new]}}
# 在指定的行号和列号处打开文件
zed {{路径/到/文件}}:{{行号}}:{{列号}}

# 在 4 字节边界上对齐一个 Zip 文件的数据
zipalign 4 {{路径/到/输入.zip}} {{路径/到/输出.zip}}
# 检查一个 Zip 文件是否在 4 字节边界上正确对齐，并以详细的方式显示结果
zipalign -v -c 4 {{路径/到/输入.zip}}

# 运行命令
, {{命令 -带 -参数}}
# 将命令添加到子 shell 中
, {{[-s|--shell]}} {{命令}}
# 清除缓存
, {{[-e|--empty-cache]}}

# 汇编一个文件，输出为 a.out
as {{路径/到/文件.s}}
# 汇编文件，并指定输出文件
as {{路径/到/文件.s}} -o {{路径/到/输出.o}}
# 通过跳过空格和注释的预处理过程来更快的产生输出文件（只应该用于可信任的编译器的输出）
as -f {{路径/到/文件.s}}
# 将给定路径添加到目录列表，来搜索.include 指令指定的文件
as -I {{目标文件夹}} {{路径/到/文件.s}}

# 打包一个文件或目录
asar {{[p|pack]}} {{文件或目录路径}} {{输出的 asar 文件}}
# 解压一个 asar 文件
asar {{[e|extract]}} {{asar 文件}}
# 从 asar 文件中解压指定的文件
asar {{[ef|extract-file]}} {{asar 文件}} {{文件}}
# 列出一个 asar 文件中的内容
asar {{[l|list]}} {{asar 文件}}

# 扫描一个二进制文件
binwalk {{二进制文件}}
# 解压一个二进制文件并指定输出目录
binwalk {{[-e|--extract]}} {{[-C|--directory]}} {{输出目录}} {{二进制文件}}
# 递归解压一个二进制文件并限制递归深度为 2
binwalk {{[-e|--extract]}} {{[-M|--matryoshka]}} {{[-d|--depth]}} 2 {{二进制文件}}
# 解压一个二进制文件并指定文件签名
binwalk {{[-D|--dd]}} '{{png image:png}}' {{二进制文件}}

# 执行自动启动文件夹中的所有程序
dex {{[-a|--autostart]}}
# 执行指定文件夹中的所有程序
dex {{[-a|--autostart]}} {{[-s|--search-paths]}} {{路径/到/目录1}}:{{路径/到/目录2}}:{{路径/到/目录3}}:
# 预览在 GNOME 特定自动启动中会执行的程序
dex {{[-a|--autostart]}} {{[-e|--environment]}} {{GNOME}}
# 预览在常规自动启动中会执行的程序
dex {{[-a|--autostart]}} {{[-d|--dry-run]}}

# 使用自动重载运行 FastAPI 应用（用于开发）
fastapi run {{路径/文件.py}} --reload
# 在开发模式下运行应用
fastapi dev {{路径/文件.py}}
# 指定运行的主机和端口
fastapi run {{路径/文件.py}} --host {{主机地址}} --port {{端口}}
# 设置应用变量名（如果不是 `app`）或指定自定义应用目录
fastapi run {{路径/文件.py}} --app-dir {{路径/到/应用}} --app {{自定义_app_名称}}

# 将当前目录中的所有文件递归归档到 `.jar` 文件中
jar cf {{file.jar}} *
# 将 `.jar` / `.war` 文件解压缩到当前目录
jar -xvf {{file.jar}}
# 列出 `.jar` / `.war` 文件内容
jar tf {{path/to/file.jar}}
# 列出带有详细输出的 `.jar` / `.war` 文件内容
jar tvf {{path/to/file.jar}}

# 运行在 justfile 中指定的配方
just {{配方}}
# 在项目根目录初始化新的 justfile
just --init
# 在默认编辑器中编辑 justfile
just {{[-e|--edit]}}
# 列出 justfile 中可用的配方
just {{[-l|--list]}}

# 将一个没有依赖项的特定目标文件链接到可执行文件中
ld {{路径/到/文件.o}} {{[-o|--output]}} {{路径/到/输出_可执行文件}}
# 将两个目标文件链接在一起
ld {{路径/到/文件1.o}} {{路径/到/文件2.o}} {{[-o|--output]}} {{路径/到/输出_可执行文件}}
# 将一个 x86_64 程序动态链接到 glibc (文件路径根据系统而变化)
ld {{[-o|--output]}} {{路径/到/输出_可执行文件}} {{[-I|--dynamic-linker]}} /lib/ld-linux-x86-64.so.2 /lib/crt1.o /lib/crti.o -lc {{路径/到/文件.o}} /lib/crtn.o

# 连接数据库
mysql {{数据库名}}
# 连接到数据库，系统将提示用户输入密码
mysql {{[-u|--user]}} {{用户名}} {{[-p|--password]}} {{数据库名}}
# 连接到另一台主机上的数据库
mysql {{[-h|--host]}} {{数据库地址}} {{数据库名}}
# 通过 Unix 套接字文件连接到数据库
mysql {{[-S|--socket]}} {{路径/到/socket.sock}}

# 从文件中导入一个已有补丁
quilt import {{路径/到/文件名.patch}}
# 创建一个新补丁
quilt new {{文件名.patch}}
# 将文件添加到当前补丁
quilt add {{路径/到/文件}}
# 编辑文件后，用更改刷新当前补丁
quilt refresh

# 显示 ELF 所有文件信息
readelf -all {{path/to/binary}}
# 显示 ELF 文件的所有头信息
readelf --headers {{path/to/binary}}
# 如果存在符号表项，则显示 ELF 文件内的符号表项
readelf --symbols {{path/to/binary}}
# 显示 ELF 文件头信息
readelf --file-header {{path/to/binary}}

# 连接到一个特定的数据库
usql {{sqlserver|mysql|postgres|sqlite3|...}}://{{用户名}}:{{密码}}@{{主机}}:{{端口}}/{{数据库名}}
# 从文件中执行命令
usql {{[-f|--file]}} {{路径/到/文件.sql}}
# 执行一个特定的 SQL 命令
usql {{[-c|--command]}} "{{sql命令}}"
# [交互式] 在 `usql` 提示符下运行一个 SQL 命令
{{sql命令}}

# 创建新环境
virtualenv {{path/to/venv}}
# 自定义提示符
virtualenv --prompt {{prompt_prefix}} {{path/to/venv}}
# 为虚拟环境使用不同的 Python 版本
virtualenv {{[-p|--python]}} {{path/to/pythonbin}} {{path/to/venv}}
# 启动（选择）环境
source {{path/to/venv}}/bin/activate

# 显示将要进行的更改的差异，但不实际更改（试运行）
yapf --diff {{路径/到/文件}}
# 就地格式化文件，并显示更改的差异
yapf --diff --in-place {{路径/到/文件}}
# 递归格式化目录中的所有 Python 文件，并发执行
yapf --recursive --in-place --style {{pep8}} --parallel {{路径/到/目录}}

# 从 `stdin` 中给定的 XML 生成一个 Go 结构体，并将输出显示在 `stdout` 上
cat {{路径/到/输入.xml}} | zek
# 从 `stdin` 中给定的 XML 生成一个 Go 结构体，并将输出发送到文件
curl {{[-s|--silent]}} {{https://url/to/xml}} | zek -o {{路径/到/输出.go}}
# 从 `stdin` 中给定的 XML 生成一个示例 Go 程序，并将输出发送到文件
cat {{路径/到/输入.xml}} | zek -p -o {{路径/到/输出.go}}

pkg.example:
# 用默认的构建文件 `build.xml` 构建一个项目
ant
# 使用 `build.xml` 以外的构建文件构建项目
ant {{[-f|-buildfile]}} {{构建文件.xml}}
# 打印该项目可能的目标信息
ant {{[-p|-projecthelp]}}
# 打印调试信息
ant {{[-d|-debug]}}

# 下载包：<http://atom.io/packages> 和主题 <http://atom.io/themes>
apm install {{包名}}
# 移除包 / 主题
apm remove {{包名}}
# 升级包 / 主题
apm upgrade {{包名}}

# 可用插件清单
asdf plugin list all
# 安装插件
asdf plugin add {{插件名}}
# 软件包的可用版本清单
asdf list all {{软件包名}}
# 安装指定版本的软件包
asdf install {{软件包名}} {{版本}}

# 根据关键词和标签“隐私”查找书签
buku {{关键词}} {{[-t|--stag]}} {{隐私}}
# 添加书签，并且打上标签“搜索引擎”和“隐私”
buku {{[-a|--add]}} {{https://example.com}} {{搜索引擎}}, {{隐私}}
# 删除一个书签
buku {{[-d|--delete]}} {{书签 id}}
# 打开编辑器，修改书签
buku {{[-w|--write]}} {{书签 id}}

# 将最新版本的依赖项添加到当前项目
cargo add {{依赖项}}
# 添加特定版本的依赖项
cargo add {{依赖项}}@{{版本号}}
# 添加依赖项并启用一个或多个特定功能
cargo add {{依赖项}} {{[-F|--features]}} {{功能1,功能2,...}}
# 添加一个可选的依赖项，然后将其作为包（crate）的一个功能暴露出来
cargo add {{依赖项}} --optional

# 从 <https://crates.io> 安装一个软件包
cargo binstall {{软件包}}
# 安装指定版本的软件包（默认为最新版本）
cargo binstall {{软件包}}@{{版本号}}
# 安装软件包并禁用确认提示
cargo binstall {{[-y|--no-confirm]}} {{软件包}}

# 检查当前软件包
cargo {{[c|check]}}
# 检查所有测试
cargo {{[c|check]}} --tests
# 检查 `tests/integration_test1.rs` 中的集成测试
cargo {{[c|check]}} --test {{integration_test1}}
# 使用 `feature1` 和 `feature2` 功能检查当前软件包
cargo {{[c|check]}} {{[-F|--features]}} {{feature1,feature2}}

# 显示 <https://crates.io> 上一个软件包的信息
cargo info {{软件包}}
# 显示一个软件包的特定版本的信息
cargo info {{软件包}}@{{版本}}
# 显示一个软件包的额外信息
cargo info {{[-v|--verbose]}} {{软件包}}

# 从 <https://crates.io> 安装一个软件包 (版本是可选的，默认为最新版本)
cargo install {{软件包}}@{{版本号}}
# 从指定的 Git 仓库安装一个软件包
cargo install --git {{仓库url}}
# 从 Git 仓库安装时，根据指定的 branch/tag/commit 构建
cargo install --git {{仓库url}} --{{branch|tag|rev}} {{branch_name|tag|commit_hash}}
# 从本地目录安装一个软件包
cargo install --path {{路径/到/软件包}}

# 邀请指定的用户或团队作为所有者
cargo owner {{[-a|--add]}} {{用户名|github:机构名称:团队名称}} {{包名}}
# 将指定的用户或团队从所有者中删除
cargo owner {{[-r|--remove]}} {{用户名|github:机构名称:团队名称}} {{包名}}
# 列出一个包（crate）的所有者
cargo owner {{[-l|--list]}} {{包名}}
# 使用指定的注册表（注册表名称可以在配置中定义，默认为 <https://crates.io>）
cargo owner --registry {{名称}}

# 执行检查，创建一个 `.crate` 文件并将其上传到注册表
cargo publish
# 执行检查，创建一个 `.crate` 文件，但不上传它（相当于 `cargo package`）
cargo publish {{[-n|--dry-run]}}
# 使用指定的注册表（注册表名称可以在配置中定义，默认为 <https://crates.io>）
cargo publish --registry {{名称}}

# 从当前项目中移除一个依赖项
cargo remove {{依赖项}}
# 移除开发或构建依赖项
cargo remove --{{dev|build}} {{依赖项}}
# 移除给定目标平台的依赖项
cargo remove --target {{目标}} {{依赖项}}

# 显示一份属于未来将无法编译的包（crate）的报告
cargo report future-incompatibilities
# 显示具有指定 Cargo 生成标识符的报告
cargo report future-incompatibilities --id {{标识符}}
# 为指定的软件包显示报告
cargo report future-incompatibilities {{[-p|--package]}} {{软件包}}

# 运行默认的二进制目标
cargo {{[r|run]}}
# 运行指定的二进制文件
cargo {{[r|run]}} --bin {{名称}}
# 运行指定的示例
cargo {{[r|run]}} --example {{示例名}}
# 激活一系列以空格或逗号分隔的功能
cargo {{[r|run]}} {{[-F|--features]}} "{{功能1 功能2 ...}}"

# 构建软件包并向 `rustc` 传递选项
cargo rustc -- {{rustc_options}}
# 在 release 模式下构建，启用优化
cargo rustc {{[-r|--release]}}
# 使用针对当前 CPU 的特定架构优化编译
cargo rustc {{[-r|--release]}} -- {{[-C|--codegen]}} target-cpu=native
# 使用速度优化编译
cargo rustc -- {{[-C|--codegen]}} opt-level={{1|2|3}}

# 向 `rustdoc` 传递选项
cargo rustdoc -- {{rustdoc_options}}
# 关于文档 lint 发出警告
cargo rustdoc -- {{[-W|--warn]}} rustdoc::{{lint_name}}
# 忽略文档 lint
cargo rustdoc -- {{[-A|--allow]}} rustdoc::{{lint_name}}
# 为软件包的库生成文档
cargo rustdoc --lib

# 搜索包
cargo search {{查询词}}
# 显示 n 个结果 (默认为 10，最多为 100)
cargo search --limit {{n}} {{查询词}}

# 仅运行包含特定字符串在其名称中的测试
cargo {{[t|test]}} {{测试名称}}
# 设置并行运行测试用例的数量
cargo {{[t|test]}} -- --test-threads {{数量}}
# 在 release 模式下测试构建，启用优化
cargo {{[t|test]}} {{[-r|--release]}}
# 测试工作区中的所有包
cargo {{[t|test]}} --workspace

# 将 `Cargo.lock` 中的依赖项更新为可能的最新版本
cargo update
# 显示将会更新的内容，但实际上不写入锁定文件
cargo update {{[-n|--dry-run]}}
# 仅更新指定的依赖项
cargo update --package {{依赖项1}} --package {{依赖项2}} --package {{依赖项3}}
# 将特定依赖项设置为特定版本
cargo update --package {{依赖项}} --precise {{1.2.3}}

# 撤回指定版本的包
cargo yank {{包名}}@{{版本号}}
# 撤销撤回 (即允许再次下载)
cargo yank --undo {{包名}}@{{版本号}}
# 使用指定的注册表 (注册表名称可以在配置中定义 - 默认为 <https：//crates.io>)
cargo yank --registry {{名称}} {{包名}}@{{版本号}}

# 创建新的环境，并将指定包安装入该环境
conda create {{[-n|--name]}} {{环境_名称}} {{python=3.9 matplotlib}}
# 列出所有环境
conda info {{[-e|--envs]}}
# 激活某个环境
conda activate {{环境_名称}}
# 取消激活某个环境
conda deactivate

# 列出当前环境中的所有包
conda list
# 列出指定环境的包
conda list {{[-n|--name]}} {{环境名称}}
# 列出特定路径下安装的包
conda list {{[-p|--prefix]}} {{路径/到/环境}}
# 用 `正则表达式` 过滤安装的包
conda list {{正则表达式}}

# 安装给定版本的 node。如果版本已经安装，它将被激活
n {{版本}}
# 显示已安装的版本并以交互方式激活其中一个版本
n
# 删除一个版本
n rm {{版本}}
# 使用给定版本执行文件
n use {{版本}} {{文件.js}}

# 启用 `nix` 命令（这是一个实验性功能）
mkdir {{[-p|--parents]}} ~/.config/nix; echo 'experimental-features = nix-command flakes' >~/.config/nix/nix.conf
# 根据名称或描述在 nixpkgs 中搜索软件包
nix search nixpkgs {{search_term}}
# 启动一个 shell，使其可以访问 nixpkgs 中指定的软件包
nix shell {{nixpkgs#pkg1 nixpkgs#pkg2 nixpkgs#pkg3 ...}}
# 从 nixpkgs 中永久安装某些软件包
nix profile install {{nixpkgs#pkg1 nixpkgs#pkg2 nixpkgs#pkg3 ...}}

# 从 nixpkgs 构建包，并将结果符号链接到 `./result`
nix build {{nixpkgs#包名}}
# 构建当前目录中 Flake 的包，并显示构建日志
nix build {{[-L|--print-build-logs]}} {{.#包名}}
# 构建某目录中 Flake 的默认包
nix build {{目录路径}}
# 构建包但不创建 `result` 符号链接，而是将存储路径输出到标准输出
nix build --no-link --print-out-paths

# 通过包名在 nixpkgs 中搜索包
nix-env {{[-qaP|--query --available --attr-path]}} {{搜索词正则表达式}}
# 启动一个包含指定可用的 shell
nix-shell {{[-p|--packages]}} {{包1 包2 包3 ...}}
# 永久安装某些包
nix-env {{[-iA|--install --attr]}} {{nixpkgs.包1 nixpkgs.包2 ...}}
# 以树状格式展示存储路径（包）的所有依赖
nix-store {{[-q|--query]}} --tree /nix/store/{{校验和-包名-版本.扩展名}}

# 在 `$EDITOR` 中打开 nixpkgs 中指定包的 Nix 表达式源码
nix edit {{nixpkgs#软件包}}
# 将包的源码直接打印输出至标准输出 (`stdout`)
EDITOR=cat nix edit {{nixpkgs#软件包}}

# 列出所有已安装的软件包
nix-env {{[-q|--query]}}
# 查询已安装的软件包（支持 `正则表达式`）
nix-env {{[-q|--query]}} {{搜索模式}}
# 从 Nixpkgs 注册表中查询可用的软件包
nix-env {{[-qa|--query --available]}} {{搜索模式}}
# 从 Nixpkgs 注册表中安装软件包
nix-env {{[-iA|--install --attr]}} nixpkgs.{{软件包名称}}

# 更新当前目录下 Flake 的所有输入（依赖项）
nix flake update
# 仅更新当前目录下 Flake 的指定输入（依赖项）
nix flake update {{输入项}}
# 克隆包含 Flake 的 GitHub 仓库
nix flake clone {{github:所有者/仓库名#属性}}
# 为指定目录中的 Flake 创建缺失的锁文件记录
nix flake lock {{flake路径}}

# 从 nixpkgs 向默认配置集中安装软件包
nix profile install {{nixpkgs#软件包1 nixpkgs#软件包2 ...}}
# 将 GitHub 上某个 flake 中的软件包安装到自定义配置集
nix profile install {{github:作者/仓库/软件包}} --profile {{目录路径}}
# 列出默认配置集中当前已安装的软件包
nix profile list
# 通过名称从默认配置集移除从 nixpkgs 安装的软件包
nix profile remove {{legacyPackages.x86_64-linux.软件包}}

# 将 `nixpkgs` 固定到上游仓库的当前版本
nix registry pin {{nixpkgs}}
# 将一个条目固定至分支的最新版本，或 GitHub 仓库的特定修订版本
nix registry pin {{entry}} {{github:owner/repo/branch_or_revision}}
# 添加一个新的条目，使其始终指向 GitHub 仓库的最新版本，并能自动更新
nix registry add {{entry}} {{github:owner/repo}}
# 移除一个注册表条目
nix registry remove {{entry}}

# 启动一个用于计算 Nix 表达式的交互式环境
nix repl
# [交互式] 将所有包从某个 flake（例如 `nixpkgs`）加载到作用域中
:lf {{nixpkgs}}
# [交互式] 从表达式构建一个软件包
:b {{expression}}
# [交互式] 启动一个包含表达式所提供软件包的 shell 环境
:u {{expression}}

# 运行当前目录下软件包配置中的默认应用程序
nix run
# 运行名称与 nixpkgs 中软件包名称匹配的命令（如果需要该软件包中的其他命令，请参阅 `tldr nix shell`）
nix run nixpkgs#{{软件包}}
# 使用提供的参数运行命令
nix run nixpkgs#{{vim}} -- {{文件路径}}
# 从远程代码库运行
nix run {{远程仓库}}:{{所有者}}/{{代码库}}

# 在 `nixpkgs` 中根据软件包名称或描述进行搜索
nix search {{nixpkgs}} {{搜索关键词}}
# 显示 nixpkgs 中某个软件包的详细描述
nix search {{nixpkgs#软件包名}}
# 查看 GitHub 上某 Flake 仓库提供的所有可用软件包
nix search {{github:所有者/仓库名}}

# 从 `nixpkgs` 中选取部分软件包启动交互式 Shell
nix shell {{nixpkgs#包1 nixpkgs#软件包组.包2 ...}}
# 使用旧版 `nixpkgs`（21.05）中的软件包启动 Shell
nix shell {{nixpkgs/nixos-21.05#软件包}}
# 从当前目录的 flake 使用“默认软件包”启动 Shell（若发生构建则显示日志）
nix shell -L
# 使用 GitHub 上 flake 中的软件包启动 Shell
nix shell {{github:所有者/仓库#软件包}}

# 显示当前运行的 NixOS 系统为何需要某个存储路径
nix why-depends {{/run/current-system}} /nix/store/{{checksum-package-version.ext}}
# 显示 nixpkgs 中的某个包为何将另一个包作为构建时依赖
nix why-depends --derivation {{nixpkgs#dependent}} {{nixpkgs#dependency}}

# 构建指定拉取请求中更改的软件包
nixpkgs-review pr {{pr_number|pr_url}}
# 构建更改的软件包并发布带报告的评论（需在 `hub`、`gh` 或 `$GITHUB_TOKEN` 环境变量中配置令牌）
nixpkgs-review pr --post-result {{pr_number|pr_url}}
# 构建更改的软件包并打印报告
nixpkgs-review pr --print-result {{pr_number|pr_url}}
# 构建本地提交中更改的软件包
nixpkgs-review rev {{HEAD}}

# 安装/卸载指定版本的 Node.js
nvm {{install|uninstall}} {{node_版本}}
# 在当前 shell 中使用指定版本的 Node.js
nvm use {{node_版本}}
# 设置默认的 Node.js 版本
nvm alias default {{node_版本}}
# 列出可安装的远程版本，仅显示 LTS（长期支持）版本
nvm ls-remote --lts

# 安装包
pip install {{包名}}
# 安装指定版本的包
pip install {{包名}}=={{版本号}}
# 通过指定的依赖文件安装（通常文件名是 `requirements.txt`）
pip install {{[-r|--requirement]}} {{requirements.txt}}
# 通过 URL 或源码存档文件安装（如 `.tar.gz` 或 `.whl`）
pip install {{[-f|--find-links]}} {{url|存档文件}}

# 向工具链添加组件
rustup component add --toolchain {{工具链}} {{组件}}
# 从工具链中移除组件
rustup component remove --toolchain {{工具链}} {{组件}}
# 列出工具链已安装和可用的组件
rustup component list --toolchain {{工具链}}
# 列出工具链已安装的组件
rustup component list --toolchain {{工具链}} --installed

# 下载并运行 `rustup-init` 来安装 `rustup` 和默认 Rust 工具链
curl https://sh.rustup.rs {{[-sSf|--silent --show-error --fail]}} | sh -s
# 下载并运行 `rustup-init` 并传递参数
curl https://sh.rustup.rs {{[-sSf|--silent --show-error --fail]}} | sh -s -- {{参数}}
# 运行 `rustup-init` 并指定要安装的额外组件或目标
rustup-init.sh --target {{目标}} --component {{组件}}
# 运行 `rustup-init` 并指定要安装的默认工具链
rustup-init.sh --default-toolchain {{工具链}}

# 查看默认工具链中某个命令的 man 手册页
rustup man {{命令}}
# 查看指定工具链中某个命令的 man 手册页
rustup man --toolchain {{工具链}} {{命令}}

# 设置默认目标平台
rustup set default-host {{目标平台}}
# 设置默认安装配置（`minimal` 只包含 `rustc`、`rust-std` 和 `cargo`，而 `default` 还会安装 `rust-docs`、`rustfmt` 和 `clippy`）
rustup set profile {{minimal|default}}
# 设置在执行 `rustup update` 时是否自动更新 `rustup` 本身
rustup set auto-self-update {{enable|disable|check-only}}

# 为工具链添加目标平台
rustup target add --toolchain {{工具链}} {{目标}}
# 从工具链移除目标平台
rustup target remove --toolchain {{工具链}} {{目标}}
# 列出工具链的可用目标平台和已安装目标平台
rustup target list --toolchain {{工具链}}
# 列出工具链已安装的目标平台
rustup target list --toolchain {{工具链}} --installed

# 安装或更新指定工具链
rustup toolchain install {{工具链}}
# 卸载工具链
rustup toolchain uninstall {{工具链}}
# 列出已安装的工具链
rustup toolchain list
# 通过创建符号链接来创建自定义工具链
rustup toolchain link {{自定义工具链名称}} {{path/to/directory}}

# 显示默认工具链中命令的二进制文件路径
rustup which {{命令}}
# 显示指定工具链中命令的二进制文件路径（有关工具链的更多信息，请参见 `rustup help toolchain`）
rustup which --toolchain {{工具链}} {{命令}}

# 添加一个包（最新版本）
uv add {{包名}}
# 添加多个包
uv add {{包1 包2 ...}}
# 添加一个包，并限制其版本
uv add {{包名>=1.2.3}}
# 将包添加到可选依赖组，并在发布时包含在内
uv add --optional {{可选依赖组}} {{包1 包2 ...}}

# 安装一个包
uv pip install {{包名}}
# 根据程序包依赖需求文件，安装程序包
uv pip install {{[-r|--requirements]}} {{requirements.txt}}
# 安装特定版本的一个包
uv pip install {{包名==1.2.3}}
# 卸载一个包
uv pip uninstall {{包名}}

# 列出所有可用的 Python 安装
uv python list
# 安装某个版本的 Python
uv python install {{版本}}
# 卸载某个版本的 Python
uv python uninstall {{版本}}
# 搜索某个版本的 Python 安装
uv python find {{版本}}

# 运行一个来自软件包的命令，而不安装它
uv tool run {{命令}}
# 在系统范围内安装一个 Python 软件包
uv tool install {{软件包}}
# 升级已安装的 Python 软件包
uv tool upgrade {{软件包}}
# 卸载一个 Python 软件包
uv tool uninstall {{软件包}}

# 在默认位置创建虚拟环境（`.venv`）
uv venv
# 在特定路径下创建一个虚拟环境
uv venv {{路径/到/虚拟环境}}
# 使用特定的 Python 版本创建
uv venv --python {{3.12}}
# 使用自定义提示词前缀进行创建
uv venv --prompt {{我的_项目}}

# 使用特定模块（例如 path 模块）
x {{module}}
# 全局安装一个软件包（例如 jq）
x env use {{package}}
# 在当前 Shell 会话中临时尝试软件包
x env try {{package}}
# 无需安装直接使用软件包
x {{package}}

# 添加一个软件包
ya pack -a {{软件包}}
# 升级所有软件包
ya pack -u
# 订阅来自所有远程实例的消息
ya sub {{种类}}
# 向当前实例发布一个字符串内容的消息
ya pub --str {{字符串消息}}

# 设置或更新 yadm 的 Git 配置
yadm config {{键.内键}} {{值}}
# 从 yadm 的 Git 配置中获取一个值
yadm config --get {{键}}
# 在 yadm 的 Git 配置中取消设置一个值
yadm config --unset {{键}}
# 列出 yadm 的 Git 配置中的所有值
yadm config --list

# 更新或设置一个 Git 配置值
yadm gitconfig {{键.内键}} {{值}}
# 从 yadm 的 Git 配置中获取一个值
yadm gitconfig --get {{键}}
# 在 yadm 的 Git 配置中取消设置一个值
yadm gitconfig --unset {{键}}
# 列出 yadm 的 Git 配置中的所有值
yadm gitconfig --list

# 执行
yadm init
# 覆盖工作树
yadm init -w {{路径/到/工作树文件夹}}
# 覆盖已存在的代码仓库
yadm init -f {{路径/到/本地代码仓库}}

# 交互式创建包含你的 AUR 用户名和密码的 `~/.config/aurvote` 文件
aurvote --configure
# 为一个或多个 AUR 包投票
aurvote {{package1 package2 ...}}
# 为一个或多个 AUR 包取消投票
aurvote {{[-u|--unvote]}} {{package1 package2 ...}}
# 检查一个或多个 AUR 包是否已投票
aurvote {{[-c|--check]}} {{package1 package2 ...}}

disk.example:
# 归档一个文件或目录
7z a {{归档文件.7z}} {{文件或目录}}
# 对已存在的归档文件加密（包括文件名）
7z a {{加密文件.7z}} -p{{密码}} -mhe=on {{归档文件.7z}}
# 提取一个已存在的 7z 文件，并保持原来的目录结构
7z x {{归档文件.7z}}
# 提取一个归档文件到指定的输出目录
7z x {{归档文件.7z}} -o{{输出目录}}

# 归档一个文件或目录
7za a {{归档文件.7z}} {{文件或目录}}
# 加密一个已存在的归档文件（包括文件名）
7za a {{加密文件.7z}} -p{{密码}} -mhe={{on}} {{归档文件.7z}}
# 提取一个已存在的 7z 文件，并保持原来的目录结构
7za x {{归档文件.7z}}
# 提取一个归档文件到指定目录
7za x {{归档文件.7z}} -o{{输出目录}}

# 归档一个文件或目录
7zr a {{归档文件.7z}} {{文件或目录}}
# 加密一个已存在的归档文件（包括文件名）
7zr a {{加密文件.7z}} -p{{密码}} -mhe={{on}} {{归档文件.7z}}
# 提取一个已存在的 7z 文件，并保持原来的目录结构
7zr x {{归档文件.7z}}
# 提取一个归档文件到指定的输出目录
7zr x {{归档文件.7z}} -o{{输出目录}}

# 从库文件中提取全部成员
ar x {{a 文件}}
# 列出库文件中的成员
ar t {{a 文件}}
# 替换或添加文件到库文件
ar r {{要被添加内容的 a 文件}} {{o 文件1 o 文件2 o 文件3 ...}}
# 插入对象文件索引（相当于使用`ranlib`）
ar s {{a 文件}}

# 将存档解压缩到当前目录
ark {{[-b|--batch]}} {{路径/到/存档名}}
# 改变解压缩目录
ark {{[-b|--batch]}} {{[-o|--destination]}} {{路径/到/目录}} {{路径/到/存档名}}
# 创建一个原本不存在的存档并向它添加文件
ark {{[-t|--add-to]}} {{路径/到/存档名}} {{路径/到/文件1 路径/到/文件2 ...}}

# 使用图片生成块图文件
bmaptool create {{[-o|--output]}} {{blockmap 格式文件.bmap}} {{图片文件}}
# 复制图片到指定目录
bmaptool copy --bmap {{blockmap 格式文件}} {{图片文件}} {{/开发路径/sdb}}
# 复制压缩后的图片到指定目录
bmaptool copy --bmap {{blockmap 格式文件}} {{图片文件.gz}} {{/开发路径/sdb}}
# 复制图片的时候，不将图片转成块图
bmaptool copy --nobmap {{图片文件}} {{/开发路径/sdb}}

# 创建子卷
sudo btrfs {{[su|subvolume]}} {{[c|create]}} {{指向子卷的路径}}
# 列出子卷
sudo btrfs {{[su|subvolume]}} {{[l|list]}} {{指向挂载点的路径}}
# 显示空间使用情况信息
sudo btrfs {{[f|filesystem]}} df {{指向挂载点的路径}}
# 启用配额（quota）
sudo btrfs {{[qu|quota]}} {{[e|enable]}} {{指向子卷的路径}}

# 将一个或多个设备添加到 btrfs 文件系统中
sudo btrfs {{[d|device]}} {{[a|add]}} {{指向设备1的路径 指向设备2的路径 ...}} {{指向 btrfs 文件系统的路径}}
# 从 btrfs 文件系统中删除设备
sudo btrfs {{[d|device]}} {{[rem|remove]}} {{指向设备1的路径|设备 ID1 指向设备2的路径|设备 ID2 ...}}
# 显示错误统计
sudo btrfs {{[d|device]}} {{[st|stats]}} {{指向 btrfs 文件系统的路径}}
# 扫描所有磁盘并将所有检测到的 btrfs 文件系统通知内核
sudo btrfs {{[d|device]}} {{[sc|scan]}} {{[-d|--all-devices]}}

# 显示文件系统使用情况（可以选择以 root 身份运行以显示详细信息）
btrfs filesystem usage {{指向挂载点的路径}}
# 显示各个设备的使用情况
sudo btrfs filesystem show {{指向挂载点的路径}}
# 对 btrfs 文件系统上的单个文件进行碎片整理（避免在运行数据去重的同时运行）
sudo btrfs filesystem defragment -v {{指向文件的路径}}
# 递归对目录进行碎片整理（不跨越子卷边界）
sudo btrfs filesystem defragment -v -r {{指向目录的路径}}

# 开始 scrub
sudo btrfs {{[sc|scrub]}} start {{指向挂载点的路径}}
# 显示正在进行或上次完成的 scrub 的状态
sudo btrfs {{[sc|scrub]}} status {{指向挂载点的路径}}
# 取消正在进行的 scrub
sudo btrfs {{[sc|scrub]}} {{[c|cancel]}} {{指向挂载点的路径}}
# 恢复先前取消的 scrub
sudo btrfs {{[sc|scrub]}} {{[r|resume]}} {{指向挂载点的路径}}

# 从标准输入读取文件名列表，并以 cpio 二进制格式将文件写入归档（copy-[o]ut 模式）
echo "{{路径/到/文件1 路径/到/文件2 ...}}" | cpio {{[-o|--create]}} >{{目标文件.cpio}}
# 递归复制目录中的所有文件和子目录并写入归档（copy-[o]ut 模式），同时显示详细输出
find {{路径/到/目录}} | cpio {{[-ov|--create --verbose]}} >{{目标文件.cpio}}
# 从归档中提取所有文件（copy-[i]n 模式），按需创建目录，同时显示详细输出
cpio <{{源文件.cpio}} {{[-idv|--extract --make-directories --verbose]}}

# 使用口令初始化 LUKS 卷
cryptsetup luksFormat {{/dev/sdXY}}
# 使用密钥文件初始化 LUKS 卷
cryptsetup luksFormat {{/dev/sdXY}} {{路径/到/密钥文件}}
# 使用口令初始化 LUKS 卷并设置其标签
cryptsetup luksFormat --label {{标签}} {{/dev/sdXY}}

# 从 isohybrid 文件（如 `archlinux-xxx.iso`）创建可启动 USB 驱动器并显示进度
sudo dd status=progress if={{路径/到/文件.iso}} of={{/dev/usb_drive}}
# 以 4 MiB 块大小克隆驱动器到另一个驱动器，并在命令终止前刷新写入
sudo dd bs=4M conv=fsync if={{/dev/源驱动器}} of={{/dev/目标驱动器}}
# 使用内核随机驱动程序生成具有指定数量随机字节的文件
dd bs={{100}} count={{1}} if=/dev/urandom of={{路径/到/随机文件}}
# 测试磁盘的写入性能
dd bs={{1M}} count={{1024}} if=/dev/zero of={{路径/到/1GB文件}}

# 压缩文件，将其替换为 `gzip` 存档文件
gzip {{路径/到/文件}}
# 解压缩文件，将其替换为原始未压缩版本
gzip {{[-d|--decompress]}} {{路径/到/文件.gz}}
# 压缩文件，保留原始文件
gzip {{[-k|--keep]}} {{路径/到/文件}}
# 压缩文件，指定输出文件名
gzip {{[-c|--stdout]}} {{路径/到/文件}} >{{路径/到/压缩文件.gz}}

# 将一个 MTP 设备挂载到一个目录
jmtpfs {{路径/到/目录}}
# 设置挂载选项
jmtpfs -o {{allow_other,auto_unmount}} {{路径/到/目录}}
# 列出可用的 MTP 设备
jmtpfs {{[-l|--listDevices]}}
# 如果存在多个设备，挂载一个特定的设备
jmtpfs -device={{总线_id}},{{设备_id}} {{路径/到/目录}}

# 以树状格式列出所有存储设备
lsblk
# 同时列出空设备
lsblk {{[-a|--all]}}
# 以字节为单位而不是以人类可读的格式打印 SIZE 列
lsblk {{[-b|--bytes]}}
# 输出文件系统信息
lsblk {{[-f|--fs]}}

# 计算一个或多个文件的 MD5 校验和
md5sum {{路径/到/文件1 路径/到/文件2 ...}}
# 计算并将 MD5 校验和列表保存到一个文件中
md5sum {{路径/到/文件1 路径/到/文件2 ...}} >{{路径/到/文件.md5}}
# 从 `stdin` 计算 MD5 校验和
{{命令}} | md5sum
# 读取包含 MD5 校验和和文件名的文件，并验证所有文件的校验和是否匹配
md5sum {{[-c|--check]}} {{路径/到/文件.md5}}

# 在分区上建立一个 Linux ext2 文件系统
sudo mkfs {{path/to/partition}}
# 建立指定类型的文件系统
sudo mkfs {{[-t|--type]}} {{ext4}} {{path/to/partition}}
# 建立指定类型的文件系统并检查坏块
sudo mkfs -c {{[-t|--type]}} {{ntfs}} {{path/to/partition}}

# 在单个设备上创建一个 btrfs 文件系统
sudo mkfs.btrfs --metadata single --data single {{/dev/sda}}
# 在多个设备上使用 raid1 创建一个 btrfs 文件系统
sudo mkfs.btrfs --metadata raid1 --data raid1 {{/dev/sda}} {{/dev/sdb}} {{/dev/sdN}}
# 为文件系统设置一个标签（可选）
sudo mkfs.btrfs --label "{{label}}" {{/dev/sda}} [{{/dev/sdN}}]

# 在设备 b 的第 1 个分区内创建一个 ROM 文件系统（`sdb1`）
mkfs.cramfs {{/dev/sdb1}}
# 创建一个带有卷名的 ROM 文件系统
mkfs.cramfs -n {{volume_name}} {{/dev/sdb1}}

# 在设备 b 的分区 1 内创建一个 exFAT 文件系统（`sdb1`）
sudo mkfs.exfat {{/dev/sdb1}}
# 创建一个带有卷名的文件系统
sudo mkfs.exfat {{[-L|--volume-label]}} {{volume_name}} {{/dev/sdXY}}
# 创建一个带有卷 ID 的文件系统
sudo mkfs.exfat {{[-U|--volume-guid]}} {{volume_id}} {{/dev/sdXY}}

# 在设备 b 的分区 1 内创建一个 ext4 文件系统（`sdb1`）
sudo mkfs.ext4 {{/dev/sdb1}}
# 创建一个带有卷标签的 ext4 文件系统
sudo mkfs.ext4 -L {{volume_label}} {{/dev/sdb1}}

# 在设备 b 的第 1 个分区内创建一个 F2FS 文件系统（`sdb1`）
sudo mkfs.f2fs {{/dev/sdb1}}
# 创建一个带有卷标签的 F2FS 文件系统
sudo mkfs.f2fs -l {{volume_label}} {{/dev/sdb1}}

# 在设备 b 的分区 1 内创建一个 FAT 文件系统（`sdb1`）
mkfs.fat {{/dev/sdb1}}
# 创建一个带有卷名的文件系统
mkfs.fat -n {{volume_name}} {{/dev/sdb1}}
# 创建一个带有卷 ID 的文件系统
mkfs.fat -i {{volume_id}} {{/dev/sdb1}}
# 使用 5 个而不是 2 个文件分配表
mkfs.fat -f 5 {{/dev/sdb1}}

# 在设备 b 的分区 1 内创建一个 NTFS 文件系统（`sdb1`）
sudo mkfs.ntfs {{/dev/sdb1}}
# 创建一个带有卷标签的文件系统
sudo mkfs.ntfs {{[-L|--label]}} {{volume_label}} {{/dev/sdb1}}
# 创建一个带有特定 UUID 的文件系统
sudo mkfs.ntfs {{[-U|--with-uuid]}} {{uuid}} {{/dev/sdb1}}

# 以人类可读的单位显示当前用户的磁盘配额
quota {{[-s|--human-readable]}}
# 详细输出（同时显示未分配存储的文件系统上的配额）
quota {{[-v|--verbose]}}
# 安静输出（仅显示使用超过配额的文件系统上的配额）
quota {{[-q|--quiet]}}
# 打印当前用户所属组的配额
quota {{[-g|--group]}}

# 计算一个或多个文件的 SHA1 校验值
shasum {{路径/到/文件1 路径/到/文件2 ...}}
# 使用指定算法计算一个或多个文件的 SHA 校验值
shasum --algorithm {{1|224|256|384|512|512224|512256}} {{路径/到/文件1 路径/到/文件2 ...}}
# 从标准输入中获取并计算 SHA1 校验值
{{命令}} | shasum
# 计算并保存 SHA256 校验值列表到文件
shasum --algorithm 256 {{路径/到/文件1 路径/到/文件2 ...}} >{{路径/到/文件.sha256}}

# 创建存档并将其写入文件
tar cf {{目标文件.tar}} {{路径/到/文件1 路径/到/文件2 ...}}
# 创建一个 gzip 压缩文件并将其写入文件
tar czf {{目标文件.tar.gz}} {{路径/到/文件1 路径/到/文件2 ...}}
# 使用相对路径从目录创建一个 gzip 压缩文件
tar czf {{目标文件.tar.gz}} {{[-C|--directory]}} {{路径/到/目录}} .
# 详细地将（压缩的）存档文件提取到当前目录中
tar xvf {{源文件.tar.ext}}

# 卸载文件系统，通过传递挂载源的路径
umount {{路径/到/设备文件}}
# 卸载文件系统，通过传递挂载目标的路径
umount {{路径/到/挂载目录}}
# 卸载所有已挂载的文件系统（`proc` 文件系统除外）
umount -a

# 提取一个归档文件到当前目录
unar {{归档文件}}
# 提取一个归档文件到指定目录
unar {{[-o|-output-directory]}} {{路径/到/目录}} {{归档文件}}
# 如果要提取的文件已经存在，则总是覆盖
unar {{[-f|-force-overwrite]}} {{归档文件}}
# 如果要提取的文件已经存在，则总是重命名
unar {{[-r|-force-rename]}} {{归档文件}}

# 解压一个归档文件
unp {{路径/到/归档文件.zip}}
# 解压多个归档文件
unp {{路径/到/归档文件1.tar.gz}} {{路径/到/归档文件2.rar}}

# 提取文件并保留原始目录结构
unrar x {{路径/到/压缩包.rar}}
# 将文件提取到指定路径，并保留原始目录结构
unrar x {{路径/到/压缩包.rar}} {{路径/到/解压目录}}
# 提取文件到当前目录，但不保留档案中的目录结构
unrar e {{路径/到/压缩包.rar}}
# 测试档案内每个文件的完整性
unrar t {{路径/到/压缩包.rar}}

# 将指定压缩包中的所有文件和目录提取到当前目录下
unzip {{路径/到/压缩文件1.zip 路径/到/压缩文件2.zip ...}}
# 将压缩包中的所有文件和目录提取到指定目录下
unzip {{路径/到/压缩文件1.zip 路径/到/压缩文件2.zip ...}} -d {{路径/到/输出目录}}
# 从压缩包中提取文件或目录到 `stdout`（标准输出），并附带文件名
unzip -c {{路径/到/压缩文件1.zip 路径/到/压缩文件2.zip ...}}
# 提取在 Windows 上创建的压缩包，其中包含非 ASCII（例如中文或日文字符）命名的文件
unzip -O {{gbk}} {{路径/到/压缩文件1.zip 路径/到/压缩文件2.zip ...}}

# 压缩可执行文件
upx {{路径/到/文件}}
# 解压可执行文件
upx -d {{路径/到/文件}}
# 显示帮助
upx --help

# 使用 xz 压缩文件
xz {{路径/到/文件}}
# 解压 XZ 文件
xz {{[-d|--decompress]}} {{路径/到/文件.xz}}
# 使用 lzma 压缩文件
xz {{[-F|--format]}} lzma {{路径/到/文件}}
# 解压 LZMA 文件
xz {{[-d|--decompress]}} {{[-F|--format]}} lzma {{路径/到/文件.lzma}}

# 对两个通过 `gzip` 压缩的文件运行 `cmp` 命令
zcmp {{路径/到/文件1.gz}} {{路径/到/文件2.gz}}
# 将一个文件与其 gzipped 版本进行比较（假设 `.gz` 已存在）
zcmp {{路径/到/文件}}

# 比较两个文件，必要时解压它们
zdiff {{路径/到/文件1.gz}} {{路径/到/文件2.gz}}
# 将文件与同名的 `gzip` 压缩文件进行比较
zdiff {{路径/到/文件}}

# 列出所有可用的 ZFS 文件系统
zfs list
# 创建一个新的 ZFS 文件系统
zfs create {{存储池名称/文件系统名称}}
# 删除一个 ZFS 文件系统
zfs destroy {{存储池名称/文件系统名称}}
# 创建一个 ZFS 文件系统的快照
zfs snapshot {{存储池名称/文件系统名称}}@{{快照名称}}

# 在压缩文件中 grep 一个模式（区分大小写）
zgrep {{模式}} {{路径/到/压缩/文件}}
# 在压缩文件中 grep 一个模式（不区分大小写）
zgrep -i {{模式}} {{路径/到/压缩/文件}}
# 输出包含匹配模式的行数
zgrep -c {{模式}} {{路径/到/压缩/文件}}
# 显示不包含该模式的行（反转搜索功能）
zgrep -v {{模式}} {{路径/到/压缩/文件}}

# 将文件/目录添加到指定存档中
zip {{[-r|--recurse-paths]}} {{路径/到/压缩文件.zip}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}
# 从指定存档中删除文件/目录
zip {{[-d|--delete]}} {{路径/到/压缩文件.zip}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}
# 存档文件/目录，排除指定的文件/目录
zip {{[-r|--recurse-paths]}} {{路径/到/压缩文件.zip}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}} {{[-x|--exclude]}} {{路径/到/排除的文件或目录}}
# 以指定的压缩级别存档文件/目录（`0` - 最低，`9` - 最高）
zip {{[-r|--recurse-paths]}} -{{0..9}} {{路径/到/压缩文件.zip}} {{路径/到/文件或目录1 路径/到/文件或目录2 ...}}

# 从一个压缩文件中提取密码哈希，列出压缩文件中的所有文件
zip2john {{路径/到/文件.zip}}
# 仅使用特定压缩文件提取密码哈希
zip2john -o {{路径/到/压缩_文件}} {{路径/到/文件.zip}}
# 从压缩文件中提取密码哈希到一个特定文件（供 John the Ripper 使用）
zip2john -o {{路径/到/压缩_文件}} {{路径/到/文件.zip}} >{{文件.hash}}

# 加密一个 Zip 压缩档案的内容
zipcloak {{路径/到/压缩档案.zip}}
# [d]解密一个 Zip 压缩档案的内容
zipcloak {{[-d|--decrypt]}} {{路径/到/压缩档案.zip}}
# [O]将加密内容输出到一个新的 Zip 压缩档案中
zipcloak {{路径/到/压缩档案.zip}} {{[-O|--output-file]}} {{路径/到/加密.zip}}

# 在 Zip 压缩档案中搜索一个模式
zipgrep "{{搜索模式}}" {{路径/到/文件.zip}}
# 打印匹配的文件名和行号
zipgrep {{[-H|--with-filename]}} {{[-n|--line-number]}} "{{搜索模式}}" {{路径/到/文件.zip}}
# 搜索与模式不匹配的行
zipgrep {{[-v|--invert-match]}} "{{搜索模式}}" {{路径/到/文件.zip}}
# 指定在 Zip 压缩档案中要搜索的文件
zipgrep "{{搜索模式}}" {{路径/到/文件.zip}} {{要搜索的文件1 要搜索的文件2 ...}}

# 查看 Zip 压缩包中的注释
zipnote {{路径/到/文件.zip}}
# 将 Zip 压缩包中的注释提取到一个文件
zipnote {{路径/到/文件.zip}} >{{路径/到/文件.txt}}
# 从一个文件中添加/更新 Zip 压缩包中的注释
zipnote <{{路径/到/文件.txt}} -w {{路径/到/文件.zip}}

# 压缩一个文件
zlib-flate <{{路径/到/输入_文件}} -compress >{{路径/到/压缩.zlib}}
# 解压缩一个文件
zlib-flate <{{路径/到/压缩.zlib}} -uncompress >{{路径/到/输出_文件}}
# 使用指定的压缩级别压缩文件。0=最快（最差），9=最慢（最佳）
zlib-flate <{{路径/到/输入_文件}} -compress={{0..9}} >{{路径/到/压缩.zlib}}

# 将文件从 `.Z` 格式重新压缩为 gzip 格式
znew {{路径/到/文件1.Z}}
# 重新压缩多个文件，并显示每个文件所实现的压缩率%
znew -v {{路径/到/文件1.Z 路径/到/文件2.Z ...}}
# 使用最慢的压缩方法重新压缩文件（以获得最佳压缩效果）
znew -9 {{路径/到/文件1.Z}}
# 重新压缩文件，如果 `.Z` 文件比 gzip 文件小，则保留 `.Z` 文件
znew -K {{路径/到/文件1.Z}}

# 优化一个 PNG 文件
zopflipng {{输入.png}} {{输出.png}}
# 优化多个 PNG 文件并使用给定的前缀保存
zopflipng --prefix={{前缀}} {{图像1.png 图像2.png 图像3.png ...}}

# 将文件或目录添加到新的或已有的归档中
zpaq {{[a|add]}} {{路径/到/归档.zpaq}} {{路径/到/文件或目录}}
# 创建或添加到加密的归档
zpaq {{[a|add]}} -k{{密码}} {{路径/到/归档.zpaq}} {{路径/到/文件或目录}}
# 解压文件的最新版本
zpaq {{[x|extract]}} {{路径/到/归档.zpaq}}
# 列出归档内容
zpaq {{[l|list]}} {{路径/到/归档.zpaq}}

# 将一个文件压缩到一个 `.zst` 后缀的压缩文件中
zstd {{file}}
# 解压缩一个文件
zstd --decompress {{file.zst}}
# 将文件解压缩到标准输出（`stdout`）
zstd --decompress --stdout {{file.zst}}
# 使用指定的压缩等级来压缩一个文件.0 = 最差，19 = 最好（默认等级是 3）
zstd -{{level}} {{file}}

# 检测 PNG 文件中的嵌入数据
zsteg {{路径/到/image.png}}
# 使用所有已知方法检测 BMP 图像中的嵌入数据
zsteg --all {{路径/到/image.bmp}}
# 检测 PNG 中的嵌入数据，以垂直方式遍历像素并优先使用 MSB
zsteg --msb --order yx {{路径/到/image.png}}
# 在 BMP 图像中检测嵌入数据，指定要考虑的位
zsteg --bits {{1,2,3|1-3}} {{路径/到/image.bmp}}

# 丢弃设备上的所有扇区，删除所有数据
blkdiscard {{/dev/设备名}}
# 安全地丢弃设备上的所有块，删除所有数据
blkdiscard {{[-s|--secure]}} {{/dev/设备名}}
# 丢弃设备的前 100 MB
blkdiscard {{[-l|--length]}} {{100MB}} {{/dev/设备名}}

# 创建一个新的空子卷
sudo btrfs {{[su|subvolume]}} {{[c|create]}} {{指向新子卷的路径}}
# 列出指定文件系统中的所有子卷和快照
sudo btrfs {{[su|subvolume]}} {{[l|list]}} {{指向 btrfs 文件系统的路径}}
# 删除一个子卷
sudo btrfs {{[su|subvolume]}} {{[d|delete]}} {{指向子卷的路径}}
# 创建现有子卷的只读快照
sudo btrfs {{[su|subvolume]}} {{[sn|snapshot]}} -r {{指向源子卷的路径}} {{指向目标的路径}}

# 以长格式（权限、所有权、大小和修改日期）列出 Zip 文件中的所有文件
zipinfo {{路径/到/压缩包.zip}}
# 列出 Zip 文件中的所有文件
zipinfo -1 {{路径/到/压缩包.zip}}

# 列出全部磁盘与分区
sudo fdisk -l
# 进入指定磁盘的交互分区界面
sudo fdisk {{/dev/sdb}}
# 打印指定磁盘的分区表
sudo fdisk -l {{/dev/sdb}}

# 挂载指定分区到目录（需要 root）
sudo mount {{/dev/sdb1}} {{/mnt}}
# 以只读方式挂载
sudo mount -o ro {{/dev/sdb1}} {{/mnt}}
# 查看当前已挂载文件系统
mount
# 卸载挂载点
sudo umount {{/mnt}}

# 创建指定大小的空文件
truncate -s {{1G}} {{路径/到/文件}}
# 清空文件内容（大小置 0）
truncate -s 0 {{路径/到/文件}}
# 按参考文件调整大小
truncate -r {{参考文件}} {{目标文件}}

sec.example:
# 使用网站根目录模式签发证书
acme.sh --issue {{[-d|--domain]}} {{example.com}} {{[-w|--webroot]}} /{{路径/到/网站根目录}}
# 使用独立模式和 80 端口为多个域名签发证书
acme.sh --issue --standalone {{[-d|--domain]}} {{example.com}} {{[-d|--domain]}} {{www.example.com}}
# 使用独立 TLS 模式和 443 端口签发证书
acme.sh --issue --alpn {{[-d|--domain]}} {{example.com}}
# 使用运行中的 `nginx` 的配置来签发证书
acme.sh --issue --nginx {{[-d|--domain]}} {{example.com}}

# 使用自动 DNS API 模式签发证书
acme.sh --issue --dns {{dns_gd}} --domain {{example.com}}
# 使用自动 DNS API 模式签发通配符证书（用星号表示）
acme.sh --issue --dns {{dns_namesilo}} --domain {{example.com}} --domain {{*.example.com}}
# 使用 DNS 别名模式签发证书
acme.sh --issue --dns {{dns_cf}} --domain {{example.com}} --challenge-alias {{alias-for-example-validation.com}}
# 在添加 DNS 记录后，通过指定自定义的等待时间（秒），在禁用 Cloudflare / Google DNS 自动轮询的同时签发证书
acme.sh --issue --dns {{dns_namecheap}} --domain {{example.com}} --dnssleep {{300}}

# 生成一个可以用密码短语（passphrase）解密的加密文件
age {{[-p|--passphrase]}} {{[-o|--output]}} {{路径/到/已加密文件}} {{路径/到/未加密文件}}
# 用一个或多个公钥加密一个文件，这些公钥以字面形式输入
age {{[-r|--recipient]}} {{公钥}} {{[-o|--output]}} {{路径/到/已加密文件}} {{路径/到/未加密文件}}
# 用收件人文件中指定的一个或多个公钥来加密一个文件
age {{[-R|--recipients-file]}} {{路径/到/收件人文件}} {{[-o|--output]}} {{路径/到/已加密文件}} {{路径/到/未加密文件}}
# 用密码短语解密一个文件
age {{[-d|--decrypt]}} {{[-o|--output]}} {{路径/到/已解密文件}} {{路径/到/已加密文件}}

# 生成密钥对，将其保存到未加密文件，并将公钥打印到标准输出
age-keygen {{[-o|--output]}} {{路径/到/文件}}
# 将身份转换为接收者，并将公钥打印到标准输出
age-keygen -y {{路径/到/文件}}

# 生成密钥对
cosign generate-key-pair
# 对容器进行签名，并将签名存储在注册表中
cosign sign --key {{cosign.key}} {{镜像}}
# 使用存储在 Kubernetes Secret 中的密钥对容器镜像进行签名
cosign sign --key k8s://{{命名空间}}/{{密钥}} {{镜像}}
# 使用本地密钥对 blob 文件进行签名
cosign sign-blob --key {{cosign.key}} {{路径/到/文件}}

# 初始化 LUKS 卷（覆盖分区上的所有数据）
cryptsetup luksFormat {{/dev/sda1}}
# 打开 LUKS 卷并在 `/dev/mapper/目标` 创建解密映射
cryptsetup luksOpen {{/dev/sda1}} {{目标}}
# 删除已存在的映射
cryptsetup luksClose {{目标}}
# 更改 LUKS 卷的口令
cryptsetup luksChangeKey {{/dev/sda1}}

# 上传文件
ffsend upload {{路径/到/文件}}
# 下载文件
ffsend download {{url}}
# 上传带有密码的文件
ffsend upload {{路径/到/文件}} {{[-p|--password]}} {{密码}}
# 下载带有密码保护的文件
ffsend download {{url}} {{[-p|--password]}} {{密码}}

# 交互地创建 GPG 公钥和私钥
gpg {{[--full-gen-key|--full-generate-key]}}
# 不加密，仅对 `doc.txt` 进行签名（生成 `doc.txt.asc`，格式为 ASCII 码形式）
gpg --clearsign {{doc.txt}}
# 为接收者 alice@example.com 和 bob@example.com 签名并加密 `doc.txt`（生成 `doc.txt.gpg`）
gpg {{[-es|--encrypt --sign]}} {{[-r|--recipient]}} {{alice@example.com}} {{[-r|--recipient]}} {{bob@example.com}} {{doc.txt}}
# 只用密码加密 `doc.txt`（生成 `doc.txt.gpg`）
gpg {{[-c|--symmetric]}} {{doc.txt}}

# 使用密码将一个目录加密为`archive.gpg`
gpg-zip {{[-c|--symmetric]}} {{[-o|--output]}} {{archive.gpg}} {{path/to/directory}}
# 将`archive.gpg`解密到同名目录中
gpg-zip {{[-d|--decrypt]}} {{path/to/archive.gpg}}
# 列出加密的`archive.gpg`的内容
gpg-zip --list-archive {{path/to/archive.gpg}}

# 验证签名文件
gpgv {{path/to/file}}
# 使用分离式签名验证已签名的文件
gpgv {{path/to/signature}} {{path/to/file}}
# 在 keyrings 列表中添加一个文件（一个导出的钥匙也算作一个 keyring）
gpgv --keyring {{path/to/keyring_file}} {{path/to/signature}} {{path/to/file}}

# 签名一个 `.jar` 文件
jarsigner {{path/to/file.jar}} {{keystore_alias}}
# 使用特定算法对 `.jar` 文件进行签名
jarsigner -sigalg {{algorithm}} {{path/to/file.jar}} {{keystore_alias}}
# 验证 `.jar` 文件的签名
jarsigner -verify {{path/to/file.jar}}

# 破解密码哈希
john {{路径/到/hashes.txt}}
# 显示已破解的密码
john --show {{路径/到/hashes.txt}}
# 按用户标识符从多个文件中显示用户的已破解密码
john --show --users={{用户标识符}} {{路径/到/hashes1.txt 路径/到/hashes2.txt ...}}
# 使用自定义的单词列表破解密码哈希
john --wordlist={{路径/到/wordlist.txt}} {{路径/到/hashes.txt}}

# 解码一个 JWT
jwt decode {{jwt字符串}}
# 将 JWT 解码为 JSON 字符串
jwt decode {{[-j|--json]}} {{jwt字符串}}
# 将 JSON 字符串编码为 JWT
jwt encode {{[-A|--alg]}} {{HS256}} {{[-S|--secret]}} {{1234567890}} '{{json字符串}}'
# 将键值对载荷编码为 JWT
jwt encode {{[-A|--alg]}} {{HS256}} {{[-S|--secret]}} {{1234567890}} {{[-P|--payload]}} {{键=值}}

# 生成指定长度的随机密码
pwgen -y {{长度}}
# 生成安全、难以记忆的密码
pwgen -s {{长度}}
# 生成至少包含一个大写字母的密码
pwgen -c {{长度}}

# 设置用于加密的对称加密算法
yadm transcrypt {{[-c|--cipher]}} {{加密算法}}
# 提供用来派生密钥的密码
yadm transcrypt {{[-p|--password]}} {{密码}}
# 假设所有回答为“是”并接受未指定选项的默认值
yadm transcrypt {{[-y|--yes]}}
# 显示当前仓库的加密算法和密码
yadm transcrypt {{[-d|--display]}}

# 请求使用公共 zrok 服务的邀请（首先运行此命令）
zrok invite
# 使用邀请邮件中的令牌启用 zrok 环境
zrok enable {{你的令牌}}
# 为本地 Web 服务器创建一个可公开访问的 URL
zrok share public {{http://localhost:8080}}
# 创建一个仅可通过唯一令牌访问的安全共享
zrok share private {{http://localhost:3000}}

# 编码一个文件
base32 {{路径/到/文件}}
# 按特定宽度包装编码输出（“0”表示禁用包装）
base32 {{[-w|--wrap]}} {{0|76|...}} {{路径/到/文件}}
# 解码一个文件
base32 {{[-d|--decode]}} {{路径/到/文件}}
# 从标准输入编码
{{某指令}} | base32

# 编码一个文件
base64 {{路径/到/文件}}
# 按特定宽度包装编码输出（“0”表示禁用包装）
base64 {{[-w|--wrap]}} {{0|76|...}} {{路径/到/文件}}
# 解码一个文件
base64 {{[-d|--decode]}} {{路径/到/文件}}
# 从标准输入编码
{{某指令}} | base64

# 解码用 `uuencode` 编码的文件，并将结果打印到 `stdout`
uudecode {{路径/到/编码文件}}
# 解码用 `uuencode` 编码的文件，并将结果写入到一个文件中
uudecode -o {{路径/到/解码文件}} {{路径/到/编码文件}}

# 编码一个文件并将结果打印到 `stdout`
uuencode {{路径/到/输入文件}} {{解码后文件名}}
# 编码一个文件并将结果写入到一个文件
uuencode -o {{路径/到/输出文件}} {{路径/到/输入文件}} {{解码后文件名}}
# 使用 Base64 而不是默认的 uuencode 编码一个文件，并将结果写入到一个文件
uuencode {{[-m|--base64]}} -o {{路径/到/输出文件}} {{路径/到/输入文件}} {{解码后文件名}}

# 查看版本
openssl version
# 生成 RSA 私钥
openssl genrsa -out {{路径/到/key.pem}} {{2048}}
# 计算文件 SHA-256 摘要
openssl dgst -sha256 {{路径/到/文件}}
# 生成自签证书
openssl req -x509 -newkey rsa:2048 -keyout {{key.pem}} -out {{cert.pem}} -days {{365}}

container.example:
# 创建一个新的触发器、创建、搜索或资源
zapier scaffold {{trigger|search|create|resource}} {{名称}}
# 为生成的文件指定一个自定义目标目录
zapier scaffold {{trigger|search|create|resource}} {{名称}} {{[-d|--dest]}}={{路径/到/目录}}
# 在生成文件时覆盖已有文件
zapier scaffold {{trigger|search|create|resource}} {{名称}} {{[-f|--force]}}
# 从生成的文件中排除注释
zapier scaffold {{trigger|search|create|resource}} {{名称}} --no-help

# 列出某个集成的版本
zapier versions
# 包含已弃用的版本
zapier versions {{[-a|--all]}}
# 显示额外的调试输出
zapier versions {{[-d|--debug]}}
# 使用不同的输出结构列出版本
zapier versions {{[-f|--format]}} {{plain|json|raw|row|table}}

# 列出已安装的角色或集合
ansible-galaxy {{role|collection}} list
# 使用不同的详细等级搜索角色（`-v` 应该放在最后）
ansible-galaxy role search {{关键字}} -v{{vvvvv}}
# 安装或移除角色
ansible-galaxy role {{install|remove}} {{角色名称1 角色名称2 ...}}
# 创建一个新角色
ansible-galaxy role init {{角色名称}}

# 对指定的 playbook 和角色目录执行 lint 检查
ansible-lint {{路径/到/playbook_文件}} {{路径/到/角色_目录}}
# 在排除特定规则的情况下对 playbook 执行 lint 检查
ansible-lint {{[-x|--exclude-rules]}} {{规则1,规则2,...}} {{路径/到/playbook_文件}}
# 以离线模式对 playbook 执行 lint 检查，并将输出格式化为 PEP8 风格
ansible-lint {{[-o|--offline]}} {{[-p|--parseable]}} {{路径/到/playbook_文件}}
# 使用自定义规则目录对 playbook 执行 lint 检查
ansible-lint {{[-r|--rules]}} {{路径/到/自定义_规则_目录}} {{路径/到/playbook_文件}}

# 通过交互式密码提示创建新的加密保险库文件
ansible-vault create {{路径/到/保险库_文件}}
# 通过交互式密码提示编辑、查看或重新生成密钥（重新加密）现有的加密保险库文件
ansible-vault {{edit|view|rekey}} {{路径/到/保险库_文件}}
# 使用密码文件创建新的加密保险库文件
ansible-vault create --vault-password-file {{路径/到/密码_文件}} {{路径/到/保险库_文件}}
# 使用密码文件原地加密现有的明文文件
ansible-vault encrypt --vault-password-file {{路径/到/密码_文件}} {{路径/到/文件}}

# 列出所有 Docker 容器（包括停止的容器）
docker {{[ps|container ls]}} {{[-a|--all]}}
# 透过镜像启动容器，并为容器命名
docker {{[run|container run]}} --name {{容器名称}} {{镜像}}
# 启动或停止现有容器
docker container {{start|stop}} {{容器名称}}
# 从 Docker registry 中拉取镜像
docker {{[pull|image pull]}} {{镜像}}

# 查看所有服务的日志
docker compose logs
# 查看指定服务的日志
docker compose logs {{服务名}}
# 查看日志并持续跟踪新输出（类似 `tail --follow`）
docker compose logs {{[-f|--follow]}}
# 查看带时间戳的日志
docker compose logs {{[-t|--timestamps]}}

# 在正在运行的容器内，启动交互式 shell 会话
docker {{[exec|container exec]}} {{[-it|--interactive --tty]}} {{容器_名称}} {{/bin/bash}}
# 在一个运行的容器内部，后台（分离）执行一个命令
docker {{[exec|container exec]}} {{[-d|--detach]}} {{容器_名称}} {{命令}}
# 指定要运行命令的运行目录
docker {{[exec|container exec]}} {{[-it|--interactive --tty]}} {{[-w|--workdir]}} {{路径/到/文件夹}} {{容器_名称}} {{命令}}
# 在现存容器内部，后台执行一个命令，但是保持 `stdin` 开启
docker {{[exec|container exec]}} {{[-i|--interactive]}} {{[-d|--detach]}} {{容器_名称}} {{命令}}

# 显示一个容器的日志
docker {{[logs|container logs]}} {{容器_名称}}
# 显示历史日志，然后跟踪容器日志
docker {{[logs|container logs]}} {{容器_名称}} {{[-f|--follow]}}
# 显示最后 5 行日志
docker {{[logs|container logs]}} {{容器_名称}} {{[-n|--tail]}} 5
# 显示带有时间戳的日志
docker {{[logs|container logs]}} {{容器_名称}} {{[-t|--timestamps]}}

# 移除容器
docker {{[rm|container rm]}} {{容器1 容器2 ...}}
# 强制移除容器
docker {{[rm|container rm]}} {{[-f|--force]}} {{容器1 容器2 ...}}
# 移除容器以及其文件卷
docker {{[rm|container rm]}} {{[-v|--volumes]}} {{容器}}
# 显示帮助
docker {{[rm|container rm]}} --help

# 使用打上标签的 Docker 镜像的新容器中执行命令
docker {{[run|container run]}} {{镜像:标签}} {{命令}}
# 在后台运行新容器中的命令，并输出其容器 ID
docker {{[run|container run]}} {{[-d|--detach]}} {{镜像}} {{命令}}
# 以交互模式和伪终端启动一个容器，并执行指定的命令
docker {{[run|container run]}} --rm {{[-it|--interactive --tty]}} {{镜像}} {{命令}}
# 在新容器中传入环境变量并运行指定命令
docker {{[run|container run]}} {{[-e|--env]}} '{{变量名}}={{变量值}}' {{[-e|--env]}} {{变量名=变量值}} {{镜像}} {{命令}}

# 停止一个 Docker 容器
docker {{[stop|container stop]}} {{容器}}
# 停止容器，并向其发送指定信号
docker {{[stop|container stop]}} {{[-s|--signal]}} {{信号}} {{容器}}
# 停止容器，并在强制终止前等待指定秒数
docker {{[stop|container stop]}} {{[-t|--timeout]}} {{秒数}} {{容器}}
# 停止一个或多个容器
docker {{[stop|container stop]}} {{容器1 容器2 ...}}

# 列出本地的 Docker 镜像
docker {{[images|image ls]}}
# 删除未使用的 Docker 镜像
docker image prune
# 删除全部的未使用镜像（而不仅仅是那些没有打上标签的镜像）
docker image prune {{[-a|--all]}}
# 展示本地 Docker 镜像的历史
docker {{[history|image history]}} {{镜像}}

# 从 `stdin` 加载 Docker 镜像
docker <{{路径/到/镜像文件.tar}} {{[load|image load]}}
# 从指定文件加载 Docker 镜像
docker {{[load|image load]}} {{[-i|--input]}} {{路径/到/镜像文件.tar}}
# 以静默模式从指定文件加载 Docker 镜像
docker {{[load|image load]}} {{[-q|--quiet]}} {{[-i|--input]}} {{路径/到/镜像文件.tar}}

# 列出所有 Docker 镜像
docker {{[images|image ls]}}
# 列出包括中间镜像在内的所有 Docker 镜像
docker {{[images|image ls]}} {{[-a|--all]}}
# 以静默模式列出结果（仅显示数字 ID）
docker {{[images|image ls]}} {{[-q|--quiet]}}
# 列出所有未被任何容器使用的 Docker 镜像
docker {{[images|image ls]}} {{[-f|--filter]}} dangling=true

# 下载指定的 Docker 镜像
docker {{[pull|image pull]}} {{镜像}}:{{标签}}
# 以静默模式下载指定的 Docker 镜像
docker {{[pull|image pull]}} {{[-q|--quiet]}} {{镜像}}:{{标签}}
# 下载指定 Docker 镜像的所有标签
docker {{[pull|image pull]}} {{[-a|--all-tags]}} {{镜像}}
# 下载指定平台的 Docker 镜像
docker {{[pull|image pull]}} --platform {{linux/amd64}} {{镜像}}:{{标签}}

# 根据名称移除一个或多个镜像
docker {{[rmi|image rm]}} {{镜像1 镜像2 ...}}
# 强制移除镜像
docker {{[rmi|image rm]}} {{[-f|--force]}} {{镜像}}
# 移除镜像但不删除未标记的父镜像
docker {{[rmi|image rm]}} --no-prune {{镜像}}
# 显示帮助
docker {{[rmi|image rm]}} --help

# 通过将 `stdout` 重定向到 `.tar` 归档文件来保存镜像
docker {{[save|image save]}} {{镜像}}:{{标签}} >{{路径/到/文件.tar}}
# 将镜像保存到 `.tar` 归档文件
docker {{[save|image save]}} {{[-o|--output]}} {{路径/到/文件.tar}} {{镜像}}:{{标签}}
# 保存镜像的所有标签
docker {{[save|image save]}} {{[-o|--output]}} {{路径/到/文件.tar}} {{镜像名称}}
# 选择镜像的特定标签进行保存
docker {{[save|image save]}} {{[-o|--output]}} {{路径/到/文件.tar}} {{镜像名称:标签1 镜像名称:标签2 ...}}

# 从一个以空格分隔的文件列表中创建一个新的 Gist
gh gist create {{路径/文件}}
# 创建一个带有描述的新 Gist
gh gist create {{文件名}} --desc "{{描述}}"
# 编辑一个 Gist
gh gist edit {{id_或_url}}
# 列出当前登录用户所拥有的 Gist
gh gist list --limit {{int}}

# 显示指定的 issue
gh issue view {{issue_号}}
# 在默认网页浏览器中查看指定的 issue
gh issue view {{issue_号}} {{[-w|--web]}}
# 在默认网页浏览器中创建一个新 issue
gh issue {{[new|create]}} {{[-w|--web]}}
# 列出最近 10 个带有 "bug" 标签的 issue
gh issue {{[ls|list]}} {{[-L|--limit]}} 10 {{[-l|--label]}} "bug"

# 创建一个拉取请求
gh pr {{[new|create]}}
# 在本地检出指定的拉取请求
gh {{[co|pr checkout]}} {{pr_号|url|分支}}
# 查看当前分支上拉取请求所做的更改
gh pr diff
# 批准当前分支关联的拉取请求
gh pr review {{[-a|--approve]}}

# 以交互式方式创建一个拉取请求
gh pr {{[new|create]}}
# 创建一个拉取请求，并根据当前分支的提交记录自动填充标题和描述
gh pr {{[new|create]}} {{[-f|--fill]}}
# 创建一个草稿拉取请求
gh pr {{[new|create]}} {{[-d|--draft]}}
# 创建一个拉取请求并指定目标分支、标题和描述
gh pr {{[new|create]}} {{[-B|--base]}} {{目标分支}} {{[-t|--title]}} "{{标题}}" {{[-b|--body]}} "{{描述}}"

# 以交互式方式合并当前分支关联的拉取请求
gh pr merge
# 合并当前分支到指定的拉取请求
gh pr merge {{pr_号}} {{[-m|--merge]}}
# 压缩合并拉取请求，并删除该分支
gh pr merge {{pr_号}} {{[-sd|--squash --delete-branch]}}
# 变基合并拉取请求
gh pr merge {{pr_号}} {{[-r|--rebase]}}

# 查看当前分支关联的拉取请求
gh pr view
# 查看指定的拉取请求
gh pr view {{123}}
# 在默认网页浏览器中打开拉取请求
gh pr view {{[-w|--web]}}
# 在终端显示评论信息
gh pr view {{123}} {{[-c|--comments]}}

# 以交互式方式选择一个工作流以查看其最近的任务
gh workflow view
# 在默认浏览器中查看指定的工作流
gh workflow view {{id|工作流名称|文件名.yml}} {{[-w|--web]}}
# 显示指定工作流的 YAML 定义
gh workflow view {{id|工作流名称|文件名.yml}} {{[-y|--yaml]}}
# 显示指定 Git 分支或标签下的 YAML 定义
gh workflow view {{id|工作流名称|文件名.yml}} {{[-r|--ref]}} {{分支|标签名}} {{[-y|--yaml]}}

# 转换一个可视化构建器集成
zapier convert {{集成_id}} {{路径/到/目录}}
# 使用特定版本转换一个可视化构建器集成
zapier convert {{集成_id}} {{路径/到/目录}} {{[-v|--version]}}={{版本}}
# 显示额外的调试输出
zapier convert --debug

# 显示收集的分析数据的状态
zapier analytics
# 更改收集信息的详细程度
zapier analytics {{[-m|--mode]}} {{enabled|anonymous|disabled}}
# 显示额外的调试输出
zapier analytics {{[-m|--mode]}} {{enabled|anonymous|disabled}} {{[-d|--debug]}}

# 列出某个集成的历史记录
zapier history
# 显示额外的调试输出
zapier history {{[-d|--debug]}}
# 以不同的输出结构列出历史记录
zapier history {{[-f|--format]}} {{plain|json|raw|row|table}}

# 初始化一个新的 Zapier 集成
zapier init {{路径/到/目录}}
# 使用特定模板初始化一个新的 Zapier 集成
zapier init {{路径/到/目录}} {{[-t|--template]}} {{basic-auth|callback|custom-auth|digest-auth|dynamic-dropdown|files|minimal|oauth1-trello|oauth2|search-or-create|session-auth|typescript}}
# 显示额外的调试输出
zapier init {{[-d|--debug]}}

# 登录到一个 Zapier 帐户
zapier login
# 使用 SSO 部署密钥登录到一个 Zapier 帐户
zapier login {{[-s|--sso]}}
# 显示额外的调试输出
zapier login {{[-d|--debug]}}

media.example:
# 显示将执行的变动但不执行（dry-run）
2to3 {{路径/到/文件.py}}
# 将 Python 2 文件转化为 Python 3
2to3 {{[-w|--write]}} {{路径/到/文件.py}}
# 将 Python 2 语言特性转化为 Python 3
2to3 {{[-w|--write]}} {{路径/到/文件.py}} {{[-f|--fix]}} {{raw_input}} {{[-f|--fix]}} {{print}}
# 除了某个语言特性外将所有其他的 Python 2 语言特性转化为 Python 3
2to3 {{[-w|--write]}} {{路径/到/文件.py}} {{[-x|--nofix]}} {{has_key}} {{[-x|--nofix]}} {{isinstance}}

# 将图像转换为 PDF（注意：指定输出文件名是可选的）
a2ping {{图像文件}} {{输出PDF文件}}
# 使用指定的方法压缩文档
a2ping --nocompress {{none|zip|best|flate}} {{文件}}
# 如果存在，则扫描 HiResBoundingBox（默认为是）
a2ping --nohires {{文件}}
# 允许页面内容位于原点的下方和左侧（默认为否）
a2ping --below {{文件}}

# 显示可执行文件的指令地址对应源代码的文件名和行数
addr2line {{[-e|--exe]}} {{可执行文件路径}} {{地址}}
# 显示函数名、文件名和行数
addr2line {{[-e|--exe]}} {{可执行文件路径}} {{[-f|--functions]}} {{地址}}
# 将 C++ 代码函数名符号重组
addr2line {{[-e|--exe]}} {{可执行文件地址}} {{[-f|--functions]}} {{[-C|--demangle]}} {{地址}}

# 使用一个特定的扩展名（默认：`aff`）
afconvert -a {{扩展名}} {{路径/到/输入文件}} {{路径/到/输出文件1 路径/到/输出文件2 ...}}
# 使用一个特定的压缩级别（默认：`7`）
afconvert -X{{0..7}} {{路径/到/输入文件}} {{路径/到/输出文件1 路径/到/输出文件2 ...}}

# 启动 `anki`
anki
# 用一个特定的配置文件启动 `anki`
anki {{[-p|--profile]}} {{配置文件名称}}
# 以特定语言启动 `anki`
anki {{[-l|--lang]}} {{语言}}
# 从一个特定的目录而不是默认的（`~/Anki`）启动`anki`
anki {{[-b|--base]}} {{路径/到/目录}}

# 播放一个文件（会自动根据文件格式确定采样率、位深等）
aplay {{文件路径}}
# 以 2500 Hz 播放指定文件的前 10 秒
aplay --duration={{10}} --rate={{2500}} {{文件路径}}
# 以 22050 Hz，mono，8-bit，Mu-Law 和 `.au` 格式来播放指定原始文件
aplay --channels={{1}} --file-type {{raw}} --rate={{22050}} --format={{mu_law}} {{文件路径}}

# 从文件中读取图像并以 ASCII 打印
asciiart {{路径/到/图片.jpg}}
# 从 URL 中读取图像并以 ASCII 打印
asciiart {{www.example.com/image.jpg}}
# 选择输出宽度（默认为 100）
asciiart {{[-w|--width]}} {{50}} {{路径/到/图片.jpg}}
# 对 ASCII 输出进行着色
asciiart {{[-c|--color]}} {{路径/到/图片.jpg}}

# 转编译指定文件到标准输出
babel {{路径/到/文件}}
# 转编译指定文件，输入为特定文件
babel {{路径/到/输入文件}} --out-file {{路径/到/输出文件}}
# 监听文件变动触发转编译
babel {{路径/到/输入文件}} --watch
# 转编译整个目录下的 js 文件
babel {{路径/到/输入文件目录}}

# 查看本地图像或使用 URL
feh {{路径/到/图像}}
# 递归查看图像
feh --recursive {{路径/到/图像}}
# 使用无边框窗口查看图像
feh --borderless {{路径/到/图像}}
# 在浏览完最后一个图像之后退出
feh --cycle-once {{路径/到/图像}}

# 从视频中提取音频并保存为 MP3 格式
ffmpeg -i {{路径/到/video.mp4}} -vn {{路径/到/sound.mp3}}
# 将 FLAC 文件转码为红皮书 CD 格式（44100 Hz，16 位）
ffmpeg -i {{路径/到/input_audio.flac}} -ar 44100 -sample_fmt s16 {{路径/到/output_audio.wav}}
# 将视频保存为 GIF，设置高度为 1000 像素，帧率为 15
ffmpeg -i {{路径/到/video.mp4}} {{[-vf|-filter:v]}} 'scale=-1:1000' -r 15 {{路径/到/output.gif}}
# 将编号图像（如 `frame_1.jpg`、`frame_2.jpg` 等）合成为视频或 GIF
ffmpeg -f image2 -i {{路径/到/frame_%d.jpg}} {{video.mpg | video.gif}}

# 为一个或多个已被 `dot` 处理的有序有向图着色
gvcolor {{路径/到/布局1.gv 路径/到/布局2.gv ...}} >{{路径/到/输出.gv}}
# 对一个图进行布局和着色，然后将其转换为 PNG 图像
dot {{路径/到/输入.gv}} | gvcolor | dot -T {{png}} >{{路径/到/输出.png}}
# 显示帮助
gvcolor -?

# 生成 Java 源代码的文档并将结果保存在文件夹中
javadoc -d {{path/to/directory}}/ {{path/to/java_source_code}}
# 生成指定编码的文档
javadoc -docencoding {{UTF-8}} {{path/to/java_source_code}}
# 生成文档时，排除掉某些软件包
javadoc -exclude {{package_list}} {{path/to/java_source_code}}

# 通过管道将命令输出转换为 JSON
{{ifconfig}} | jc {{--ifconfig}}
# 通过魔术语法将命令输出转换为 JSON
jc {{ifconfig}}
# 通过管道输出格式化的 JSON
{{ifconfig}} | jc {{--ifconfig}} {{[-p|--pretty]}}
# 通过魔术语法输出格式化的 JSON
jc {{[-p|--pretty]}} {{ifconfig}}

# 从文件中读取 JPEG 图像并以 ASCII 显示
jp2a {{路径/到/image.jpeg}}
# 从 URL 中读取 JPEG 图像并以 ASCII 显示
jp2a {{www.example.com/image.jpeg}}
# 对 ASCII 输出进行着色
jp2a --colors {{路径/到/image.jpeg}}
# 指定用于 ASCII 输出的字符
jp2a --chars='{{..-ooxx@@}}' {{路径/到/image.jpeg}}

# 优化一组 JPEG 图像，保留所有相关数据
jpegoptim {{图像1.jpeg 图像2.jpeg 图像3.jpeg ...}}
# 优化 JPEG 图像，剥离所有非必要数据
jpegoptim {{[-s|--strip-all]}} {{图像1.jpeg 图像2.jpeg 图像3.jpeg ...}}
# 强制输出图像为渐进式
jpegoptim --all-progressive {{图像1.jpeg 图像2.jpeg 图像3.jpeg ...}}
# 强制输出图像具有固定的最大文件大小
jpegoptim {{[-S|--size]}} {{250k}} {{图像1.jpeg 图像2.jpeg 图像3.jpeg ...}}

# 将 JPEG/JFIF 图像转换为 PPM 或 PGM 图像
jpegtopnm {{路径/到/文件.jpg}} >{{路径/到/文件.pnm}}
# 显示版本
jpegtopnm {{[-v|-version]}}

# 将 JSON5 `标准输入` 转换为 JSON 并输出到 `标准输出`
echo {{输入}} | json5
# 将 JSON5 文件转换为 JSON 并输出到 `标准输出`
json5 {{路径/到/输入文件.json5}}
# 将 JSON5 文件转换为指定的 JSON 文件
json5 {{路径/到/输入文件.json5}} {{[-o|--out-file]}} {{路径/到/输出文件.json}}
# 验证一个 JSON5 文件
json5 {{路径/到/输入文件.json5}} {{[-v|--validate]}}

# 转换图片格式
magick {{路径/到/输入图片.png}} {{路径/到/输出图片.jpg}}
# 改变图片大小，生成新的副本
magick {{路径/到/输入图片.jpg}} -resize {{100x100}} {{路径/到/输出图片.jpg}}
# 利用当前目录下的所有 JPEG 图片生成一个 GIF 动图
magick {{*.jpg}} {{路径/到/GIF文件.gif}}
# 生成棋盘格图片
magick -size {{640x480}} pattern:checkerboard {{路径/到/棋盘格图片.png}}

# 比较两个图片
magick compare {{路径/到/图片1.png}} {{路径/到/图片2.png}} {{路径/到/比较图片.png}}
# 使用特定的算法比较两个图片
magick compare -verbose -metric {{PSNR}} {{路径/到/图片1.png}} {{路径/到/图片2.png}} {{路径/到/比较图片.png}}

# 将 JPEG 图片转换为 PNG 图片
magick convert {{路径/到/输入图片.jpg}} {{路径/到/输出图片.png}}
# 将图片调整至原图片尺寸的 50%
magick convert {{路径/到/输入图片.png}} -resize 50% {{路径/到/输出图片.png}}
# 在宽高都不超过 640x480 的限制下，保持图片的比例，将尺寸调整至最大
magick convert {{路径/到/输入图片.png}} -resize 640x480 {{路径/到/输出图片.png}}
# 将图片调整至特定文件大小
magick convert {{路径/到/输入图片.png}} -define jpeg:extent={{512kb}} {{路径/到/输出图片.jpg}}

# 输出图片的格式以及一些基本属性
magick identify {{路径/到/图片}}
# 输出图片的格式及其详细属性
magick identify -verbose {{路径/到/图片}}
# 将当前目录下的所有 JPEG 图片的尺寸属性
magick identify -format "{{%f,%w,%h\n}}" {{*.jpg}} >{{路径/到/文件列表.csv}}

# 捕获整个 X server 屏幕，保存为 PostScript 文件
magick import -window root {{路径/到/输出文件.ps}}
# 捕获远程 X server 屏幕，保存为 PNG 图片
magick import -window root -display {{remote_host}}:{{screen}}.{{display}} {{路径/到/输出文件.png}}
# 用 `xwininfo` 中列出的窗口 ID 对特定窗口进行捕获，保存为 JPEG 图片
magick import -window {{窗口id}} {{路径/到/输出图片.jpg}}

# 将当前目录下所有 JPEG 图片的尺寸都调整至原尺寸的 50%
magick mogrify -resize {{50%}} {{*.jpg}}
# 将当前目录下所有以 DSC 开头的图片尺寸都调整至 800x600
magick mogrify -resize {{800x600}} {{DSC*}}
# 将当前目录下所有 PNG 图片都转换为 JPEG 图片
magick mogrify -format {{jpg}} {{*.png}}
# 将当前目录下所有图片文件的饱和度都减半
magick mogrify -modulate {{100,50}} {{*}}

# 平铺图片，尺寸大于格子的图片将会被自动缩小
magick montage {{路径/到/图片1.jpg 路径/到/图片2.jpg ...}} {{路径/到/拼图图片.jpg}}
# 平铺图片，根据最大的图片来计算格子大小
magick montage {{路径/到/图片1.jpg 路径/到/图片2.jpg ...}} -geometry {{+0+0}} {{路径/到/拼图图片.jpg}}
# 平铺图片，根据指定的格子大小调整图片尺寸
magick montage {{路径/到/图片1.jpg 路径/到/图片2.jpg ...}} -geometry {{640x480+0+0}} {{路径/到/拼图图片.jpg}}
# 指定格子的行列数，如果图片数量超出格子数，则会输出复数张图片
magick montage {{路径/到/图片1.jpg 路径/到/图片2.jpg ...}} -geometry {{+0+0}} -tile {{2x3}} {{montage_%d.jpg}}

# 使用默认设置渲染 Python 脚本中的场景
manim {{路径/文件.py}} {{场景名称}}
# 实时预览渲染（渲染后自动打开视频）
manim {{[-pql|--preview --quality low]}} {{路径/文件.py}} {{场景名称}}
# 以高质量渲染（1080p 60 帧）
manim {{[-pqh|--preview --quality high]}} {{路径/文件.py}} {{场景名称}}
# 指定自定义输出文件名
manim {{[-o|--output_file]}} {{输出文件名}} {{路径/文件.py}} {{场景名称}}

# 从 URL 或文件播放视频或音频
mpv {{url|路径/到/文件}}
# 向后/向前跳跃 5 秒
{{<ArrowLeft>|<ArrowRight>}}
# 向后/向前跳跃 1 分钟
{{<ArrowDown>|<ArrowUp>}}
# 减少/增加 10% 播放速度
{{<[>|<]>}}

# 从一个 PDF 文件中提取第 1-3 页、第 5 页和第 6-10 页，然后另存为一个新文件
qpdf --empty --pages {{路径/到/输入.pdf}} {{1-3,5,6-10}} -- {{路径/到/输出.pdf}}
# 合并（连接）多个 PDF 文件的所有页面，并将结果保存为一个新 PDF
qpdf --empty --pages {{路径/到/文件1.pdf 文件2.pdf ...}} -- {{路径/到/输出.pdf}}
# 合并（连接）多个 PDF 文件中指定的页面，并将结果保存为一个新 PDF
qpdf --empty --pages {{路径/到/文件1.pdf}} {{1,6-8}} {{路径/到/文件2.pdf}} {{3,4,5}} -- {{路径/到/输出.pdf}}
# 将每组 `n` 页写入一个单独的输出文件，使用给定的文件名模式
qpdf --split-pages={{n}} {{路径/到/输入.pdf}} {{路径/到/输出_%d.pdf}}

# 从包（crate）的根文件生成文档
rustdoc {{src/lib.rs}}
# 为项目传递一个名称
rustdoc {{src/lib.rs}} --crate-name {{名称}}
# 从 Markdown 文件生成文档
rustdoc {{路径/到/文件.md}}
# 指定输出目录
rustdoc {{src/lib.rs}} {{[-o|--out-dir]}} {{路径/到/输出目录}}

# 简单地将 RAW 文件转换为 JPEG
ufraw-batch --out-type=jpg {{（或多个）输入文件}}
# 简单地将 RAW 文件转换为 PNG
ufraw-batch --out-type=png {{（或多个）输入文件}}
# 从 RAW 文件中提取预览图像
ufraw-batch --embedded-image {{（或多个）输入文件}}
# 将文件保存为不超过给定的最大尺寸 MAX1 和 MAX2
ufraw-batch --size=MAX1,MAX2 {{（或多个）输入文件}}

# 将每个文件中的空格转换为制表符，并写入到 `stdout`
unexpand {{路径/到/文件}}
# 将空格转换为制表符，从 `stdout` 读取
unexpand
# 转换所有空格，而不仅仅是开头的空格
unexpand {{[-a|--all]}} {{路径/到/文件}}
# 仅转换开头的空格序列（覆盖 -a）
unexpand --first-only {{路径/到/文件}}

# 以交互模式运行
units
# [交互式] 在交互模式下列出包含特定字符串的所有单位
search {{字符串}}
# 显示两个简单单位之间的转换
units {{quarts(夸脱)}} {{tablespoons(大汤匙)}}
# 单位与数量之间的转换
units "{{15 pounds(磅)}}" {{kilograms(公斤)}}

# 打开文档
vim {{文件}}
# 打开文件的指定行数
vim +{{行数}} {{文件}}
# 查看 Vim 的使用说明
<:>help<Enter>
# 保存并退出
{{<Esc><Z><Z>|<Esc><:>x<Enter>|<Esc><:>wq<Enter>}}

# 播放一个文件
vlc {{文件名}}
# 全屏播放
vlc --fullscreen {{文件名}}
# 静音播放
vlc --no-audio {{文件名}}
# 循环播放
vlc --loop {{文件名}}

# 搜索一个视频
youtube-viewer {{搜索关键词}}
# 登录到你的 YouTube 账户
youtube-viewer --login
# 在 VLC 中观看指定 URL 的视频
youtube-viewer --player={{vlc}} {{https://youtube.com/watch?v=dQw4w9WgXcQ}}
# 显示一个搜索提示并以 720p 播放已选视频
youtube-viewer -{{7}}

# 将 Zeiss 共聚焦文件转换为 `.pgm` 或 `.ppm` 格式
zeisstopnm {{路径/到/文件}}
# 将 Zeiss 共聚焦文件转换为 Netbpm 格式，并明确指定目标文件类型
zeisstopnm -{{pgm|ppm}} {{路径/到/文件}}

# 通过反转一些边来使有向图无环
acyclic {{路径/到/输入.gv}} >{{路径/到/输出.gv}}
# 打印出一个图是无环的、有环的还是无向的，不产生输出图
acyclic -v -n {{路径/到/输入.gv}}
# 显示帮助
acyclic -?

# 增加 10% 的主音量
amixer -D pulse sset Master {{10%+}}
# 降低 10% 的主音量
amixer -D pulse sset Master {{10%-}}

# 以 "CD" 质量录制一段声音（录制结束以 `<Ctrl c>` 停止）
arecord {{[-vv|--verbose --verbose]}} {{[-f|--format]}} cd {{路径/文件名.wav}}
# 以 "CD" 质量录制 10 秒钟声音
arecord {{[-vv|--verbose --verbose]}} {{[-f|--format]}} cd {{[-d|--duration]}} 10 {{路径/文件名.wav}}
# 录制一段声音并以 mp3 格式保存（录制结束以 `<Ctrl c>` 停止）
arecord {{[-vv|--verbose --verbose]}} {{[-f|--format]}} cd {{[-t|--file-type]}} raw | lame -r - {{路径/文件名.mp3}}
# 列出所有的声卡和数字音频设备
arecord {{[-l|--list-devices]}}

# 将一个或多个图形分解为它们的双连通分量
bcomps {{路径/到/输入1.gv 路径/到/输入2.gv ...}} >{{路径/到/输出.gv}}
# 打印一个或多个图形中的块和切割顶点的数量
bcomps -v -s {{路径/到/输入1.gv 路径/到/输入2.gv ...}}
# 根据 `输出.gv` 将每个块和块切割顶点树写入多个有编号的文件中
bcomps -x -o {{路径/到/输出.gv}} {{路径/到/输入1.gv 路径/到/输入2.gv ...}}
# 显示帮助
bcomps -?

# 播放哔哔声
beep
# 重复播放哔哔声
beep -r {{重复次数}}
# 指定频率（Hz）和持续时间（毫秒）播放哔哔声
beep -f {{频率}} -l {{持续时间}}
# 将每个新的频率和持续时间作为单独的哔哔声播放
beep -f {{频率}} -l {{持续时间}} {{[-n|--new]}} -f {{频率}} -l {{持续时间}}

# 将一个或多个图形分解为它们的连通分量
ccomps {{路径/到/输入1.gv 路径/到/输入2.gv ...}} >{{路径/到/输出.gv}}
# 打印一个或多个图形中的节点、边和连通分量的数量
ccomps -v -s {{路径/到/输入1.gv 路径/到/输入2.gv ...}}
# 根据 `输出.gv` 将每个连通分量写入多个有编号的文件中
ccomps -x -o {{路径/到/输出.gv}} {{路径/到/输入1.gv 路径/到/输入2.gv ...}}
# 显示帮助
ccomps -?

# 对一个或多个已经有布局信息的图形布局的边缘进行着色，以澄清交叉边缘
edgepaint {{路径/到/布局1.gv 路径/到/布局2.gv ...}} >{{路径/到/输出.gv}}
# 使用颜色方案对边缘进行着色。（参见：<https://graphviz.org/doc/info/colors.html#brewer>）
edgepaint -color-scheme={{accent7}} {{路径/到/布局.gv}} >{{路径/到/输出.gv}}
# 对图形进行布局并对其边缘进行着色，然后将其转换为 PNG 图像
dot {{路径/到/输入.gv}} | edgepaint | dot -T {{png}} >{{路径/到/输出.png}}
# 显示帮助
edgepaint -?

# 将多个具有布局信息的图形布局组合在一起
gvpack {{路径/到/布局1.gv 路径/到/布局2.gv ...}} >{{路径/到/输出.gv}}
# 在图形层面上将多个图形布局组合在一起，保持图形分开
gvpack -g {{路径/到/布局1.gv 路径/到/布局2.gv ...}} >{{路径/到/输出.gv}}
# 在节点层面上将多个图形布局组合在一起，忽略簇
gvpack -n {{路径/到/布局1.gv 路径/到/布局2.gv ...}} >{{路径/到/输出.gv}}
# 将多个图形布局组合在一起而不进行打包
gvpack -u {{路径/到/布局1.gv 路径/到/布局2.gv ...}} >{{路径/到/输出.gv}}

# 使用编辑器插入一个新条目
jrnl
# 快速插入一个新条目
jrnl {{today at 3am}}: {{标题}}. {{内容}}
# 查看最近的十条条目
jrnl -n {{10}}
# 查看从去年开始到今年三月初所有发生的事情
jrnl -from "{{last year}}" -until {{march}}

# 捆绑一个或多个已经有布局信息的图形布局的边缘
mingle {{路径/到/布局1.gv 路径/到/布局2.gv ...}} >{{路径/到/输出.gv}}
# 通过一个命令执行布局、捆绑和输出到图片
dot {{路径/到/输入.gv}} | mingle | dot -T {{png}} >{{路径/到/输出.png}}
# 显示帮助
mingle -?

# 将字符串转换为二维码并保存到输出文件
qrencode {{[-o|--output]}} {{路径/到/输出文件.png}} {{字符串}}
# 将输入文件转换为二维码并保存到输出文件
qrencode {{[-o|--output]}} {{路径/到/输出文件.png}} {{[-r|--read-from]}} {{路径/到/输入文件}}
# 将字符串转换为二维码并在终端中打印
qrencode {{[-t|--type]}} ansiutf8 {{字符串}}
# 从管道输入转换为二维码并在终端中打印
echo {{字符串}} | qrencode {{[-t|--type]}} utf8

# 从一个或多个有向图中提取强连通分量
sccmap -S {{路径/到/输入1.gv 路径/到/输入2.gv ...}} >{{路径/到/输出.gv}}
# 打印一个图形的统计信息，不生成输出图形
sccmap -v -s {{路径/到/输入1.gv 路径/到/输入2.gv ...}}
# 显示帮助
sccmap -?

# 打开 Thunderbird
thunderbird
# 使用特定用户配置文件
thunderbird -P {{配置文件名称}}
# 使用特定用户配置文件夹
thunderbird --profile {{路径/到/配置文件/文件夹}}

# 调整一个或多个有向图以改善布局的纵横比
unflatten {{路径/到/输入1.gv 路径/到/输入2.gv ...}} >{{路径/到/输出.gv}}
# 将 `unflatten` 作为 `dot` 布局的预处理器以改善纵横比
unflatten {{路径/到/输入.gv}} | dot -T {{png}} {{路径/到/输出.png}}
# 显示帮助
unflatten -?

# 模仿 `cmatrix` 的默认输出（无 Unicode，适用于 TTY）
unimatrix --no-bold --speed {{96}} --character-list {{o}}
# 无粗体字符，缓慢地显示，使用表情符号、数字和少量符号
unimatrix --no-bold --speed {{50}} --character-list {{ens}}
# 更改字符的颜色
unimatrix --color {{red|green|blue|white|...}}
# 使用字母代码选择字符集（可用字符集请参阅 `unimatrix --help`）
unimatrix --character-list {{character_sets}}

# 生成一个条形码并保存
zint --data "{{UTF-8 数据}}" --output {{路径/到/文件}}
# 指定生成的编码类型
zint --barcode {{编码类型}} --data "{{UTF-8 数据}}" --output {{路径/到/文件}}
# 列出所有支持的编码类型
zint --types

os.example:
# 查看过滤表的规则链、规则以及数据包/字节计数器
sudo iptables {{[-vnL --line-numbers|--verbose --numeric --list --line-numbers]}}
# 设定规则链策略规则
sudo iptables {{[-P|--policy]}} {{规则链}} {{规则}}
# 追加规则到 IP 的规则链策略
sudo iptables {{[-A|--append]}} {{规则链}} {{[-s|--source]}} {{ip_address}} {{[-j|--jump]}} {{规则}}
# 追加规则到 IP 的规则链策略（考虑协议与端口）
sudo iptables {{[-A|--append]}} {{规则链}} {{[-s|--source]}} {{ip_address}} {{[-p|--protocol]}} {{协议}} --dport {{端口}} {{[-j|--jump]}} {{规则}}

# 添加一个新的 APT 仓库
add-apt-repository {{指定仓库}}
# 移除一个 APT 仓库
add-apt-repository {{[-r|--remove]}} {{指定仓库}}
# 添加一个仓库并更新缓存
add-apt-repository --update {{指定仓库}}
# 允许从指定仓库下载源码
add-apt-repository {{[-s|--enable-source]}} {{指定仓库}}

# 从所有的远程仓库中更新仓库索引
apk update
# 安装一个新软件包
apk add {{软件包}}
# 移除一个软件包
apk del {{软件包}}
# 修复或更新软件包而不修改主依赖项
apk fix {{软件包}}

# 更新可用软件包及其版本列表（推荐在运行其他 APT 命令前首先运行该命令）
sudo apt update
# 查找指定软件包
apt search {{软件包}}
# 显示关于指定软件包的信息
apt show {{软件包}}
# 安装指定软件包或将指定软件包更新到最新版本
sudo apt install {{软件包}}

# 在当前的软件源中查找一个软件包
apt-cache search {{软件包}}
# 显示指定软件包的相关信息
apt-cache show {{软件包}}
# 查看一个软件包是否安装或是否为最新
apt-cache policy {{软件包}}
# 显示一个软件包的依赖项
apt-cache depends {{软件包}}

# 将当前系统的软件包状态克隆到指定目录
apt-clone clone {{路径/到/目录}}
# 创建克隆文件（`.tar.gz`）用于备份
apt-clone clone --destination {{路径/到/备份文件.tar.gz}}
# 从克隆文件恢复软件包状态
apt-clone restore {{路径/到/备份文件.tar.gz}}
# 显示克隆文件的信息（如发行版、架构等）
apt-clone info {{路径/到/备份文件.tar.gz}}

# 更新元数据的数据库
sudo apt update
# 查找包含指定文件或路径的软件包
apt-file {{[find|search]}} {{文件路径}}
# 列出指定包的内容
apt-file list {{软件包名}}
# 查找符合给定 `pattern` 中`regex`式的软件包
apt-file {{[find|search]}} {{[-x|--regexp]}} {{正则表达式}}

# 更新可用软件包及其版本列表（推荐在其他 `apt-get` 命令运行之前使用）
sudo apt-get update
# 安装一个软件包或更新到最新版本
sudo apt-get install {{软件包}}
# 移除一个软件包
sudo apt-get remove {{软件包}}
# 移除一个软件包及其配置文件
sudo apt-get purge {{软件包}}

# 安装软件包或将其更新至最新版本
sudo apt install {{软件包}}
# 在安装或更新过程中显示详细的软件包版本信息
sudo apt install {{[-V|--verbose-versions]}} {{软件包}}

# 将一个软件包标记为自动安装
sudo apt-mark auto {{软件包名}}
# 将一个软件包保持在当前版本，防止对其更新
sudo apt-mark hold {{软件包名}}
# 允许对一个软件包更新
sudo apt-mark unhold {{软件包名}}
# 列出手动安装的软件包
apt-mark showmanual

# 更新已安装的包到最新可用版本
sudo dnf upgrade
# 通过关键词搜索包
dnf search {{关键词1 关键词2 ...}}
# 显示软件包的描述
dnf info {{包}}
# 安装软件包（使用 `-y` 自动确认所有提示）
sudo dnf install {{包1 包2 ...}}

# 进入交互式包管理界面
sudo oma
# 安装软件包
sudo oma install {{软件包名}}
# 移除软件包
sudo oma remove {{软件包名}}
# 搜索软件包
oma search {{关键词}}

# 更新可用软件包的列表
upt update
# 搜索指定的软件包
upt search {{搜索软件包关键词}}
# 显示某个软件包的信息
upt info {{软件包}}
# 安装指定的软件包
upt install {{软件包}}

# 同步并更新所有软件包（包括 AUR）
yaourt -Syua
# 安装一个新的软件包（包括 AUR）
yaourt -S {{软件包}}
# 移除一个软件包和它的依赖（包括 AUR 软件包）
yaourt -Rs {{软件包}}
# 在软件包数据库中搜索一个关键字（包括 AUR）
yaourt -Ss {{软件包}}

# 保存当前屏幕布局
autorandr -s {{配置文件名}}
# 显示保存的配置
autorandr
# 切换设置
autorandr -l {{配置文件名}}
# 设置默认设置
autorandr -d {{配置文件名}}

# 锁定屏幕
betterlockscreen {{[-l|--lock]}}
# 更换锁屏背景
betterlockscreen {{[-u|--update]}} {{图片.png}}
# 锁屏并显示一些自定义文本
betterlockscreen {{[-l|--lock]}} pixel --text "{{自定义锁屏文本}}"
# 锁屏并自定义显示屏关闭超时秒数
betterlockscreen --off {{5}} {{[-l|--lock]}}

# 安装 GRUB 到基于 BIOS 的系统
grub-install --target={{i386-pc}} {{/dev/sdX}}
# 安装 GRUB 到基于 UEFI 的系统
grub-install --target={{x86_64-efi}} --efi-directory={{path/to/efi_directory}} --bootloader-id={{GRUB}}
# 安装预置指定模块的 GRUB
grub-install --target={{x86_64-efi}} --efi-directory={{path/to/efi_directory}} --modules="{{part_gpt part_msdos}}"

# 模拟运行并打印配置到标准输出
sudo grub-mkconfig
# 生成配置文件
sudo grub-mkconfig {{[-o|--output]}} {{/boot/grub/grub.cfg}}
# 显示帮助
grub-mkconfig {{[-h|--help]}}

# 打印所有可用信息
lsb_release {{[-a|--all]}}
# 打印操作系统的描述（通常是全名）
lsb_release {{[-d|--description]}}
# 仅打印操作系统名称 (ID)，隐藏字段名称
lsb_release {{[-is|--id --short]}}
# 打印发行版的版本号和代号，隐藏字段名称
lsb_release {{[-rcs|--release --codename --short]}}

# 以临时后台单元运行一条命令
systemd-run --unit={{名称}} {{命令}}
# 运行用户级临时单元
systemd-run --user --unit={{名称}} {{命令}}
# 设定为定时 oneshot 任务
systemd-run --on-active={{30s}} --unit={{名称}} {{命令}}

# 查看当前主机与系统信息
hostnamectl
# 修改静态主机名（需要 root）
sudo hostnamectl set-hostname {{新主机名}}
# 查看某台远程机器的信息
hostnamectl -H {{用户}}@{{主机地址}}

# 列出已安装的指定包
dpkg -l {{软件包}}
# 安装本地 .deb 包（需要 root）
sudo dpkg -i {{路径/到/包.deb}}
# 列出该包安装的所有文件
dpkg -L {{软件包}}
# 查找某个文件属于哪个包
dpkg -S {{/etc/hosts}}

# 查询指定包是否已安装
rpm -q {{软件包}}
# 列出所有已安装包
rpm -qa
# 列出该包安装的文件
rpm -ql {{软件包}}
# 安装本地 rpm 包（需要 root）
sudo rpm -ivh {{路径/到/包.rpm}}

# 列出某命令的所有候选版本
update-alternatives --list {{名称}}
# 交互式选择默认版本（需要 root）
sudo update-alternatives --config {{名称}}
# 注册一个新的候选（需要 root）
sudo update-alternatives --install /usr/bin/{{名称}} {{名称}} {{路径/到/程序}} {{优先级}}

# 从官方仓库和 AUR 检索包
aura --aursync --both --search {{包名|正则}}
# 从 AUR 安装一个软件包
aura --aursync {{包名}}
# 以详细模式升级所有的 AUR 包并移除所有的编译依赖
aura --aursync --diff --sysupgrade --delmakedeps --unsuppress
# 从官方仓库安装一个软件包
aura --sync {{包名}}

alias.example:
# 显示一个 ASCII 字符的别名
ascii {{a}}
# 以较短和脚本友好模式显示 ASCII 字符的别名
ascii -t {{a}}
# 显示多个 ASCII 字符的别名
ascii -s {{tldr}}
# 显示十进制 ASCII 字符表
ascii -d

# 跳转到包含指定通配符的目录
j {{通配符表达式}}
# 跳转到包含指定通配符的目录的下一级
jc {{通配符表达式}}
# 使用系统文件管理器，打开指定的目录
jo {{通配符表达式}}
# 从 autojump 数据库中删除不存在的目录
j --purge

# 从字面上执行 `ls` 程序，即使存在 `ls` 别名
command {{ls}}
# 显示指定命令的可执行程序路径或别名定义
command -v {{命令名}}

other.example:
# 将本地安装的 `asciinema` 与 asciinema.org 账号关联
asciinema auth
# 新建录制并保存到本地文件（按 `<Ctrl d>` 或输入 `exit` 结束）
asciinema rec {{路径/到/录制文件.cast}}
# 从本地文件回放终端录制
asciinema play {{路径/到/录制文件.cast}}
# 回放托管在 <https://asciinema.org> 的终端录制
asciinema play https://asciinema.org/a/{{文件id}}

# 启动一个 REPL 会话以进行交互式对话
qwen
# 将另一个命令的输出发送给 Qwen 并立即退出
{{echo "总结罗马的历史"}} | qwen {{[-p|--prompt]}}
# 覆盖默认模型（默认值：qwen3-coder-max）
qwen {{[-m|--model]}} {{model_name}}
# 在沙盒容器中运行
qwen {{[-s|--sandbox]}}
